// Ruach Studio · the page in Hebrew (עברית), keyed by its English (heresy-i18n.js). Made by Claude for Viktor (his word of 05.11.2026:
// «пусть начинает делать словарь иврита»), first as ten chunks read line by line against the English and the Russian (MISC/claude-i18n/he,
// 06.11.2026), then on the page from 2.0.7 (10.11.2026): the keys it gained translated, the rooms renamed, the page right to left
// (heresy-i18n.js: dir="rtl"), the Hebrew letters in Noto Sans Hebrew (OFL). {0}, {1}: the parts that change.
// The brand is נפחות רוח (Viktor 05-06.11.2026: «"Ruach Studio" в иврите обязательно на иврит»): feminine, no article, a prefix
// joined with no hyphen (בנפחות רוח). The Studio, the product, is the brand's head word הנפחות (בנפחות, לנפחות, מהנפחות; a bare
// label or one copy of it נפחות); an ordinary recording studio is אולפן; Latin "Ruach Studio" only as an identifier (the
// Pianoteq bank, repo and file names). Terms: the rooms מוזיקאי (Musician, the Creator until 10.11.2026) · כותב (Writer) ·
// מלטש (Refiner) · ספרן (Librarian) · מאמן LoRA (LoRA Trainer) · צייר (Artist, named by app.js) · וידאוגרף (Videographer) ·
// קריין (Narrator, the Reader until 10.11.2026; its own words in heresy-reader-i18n.js) · מנוע (Engine); take = טייק; workspace =
// מרחב; seed = זרע; probe = ניסוי; Debuzz = אנטי-זמזום; Reuse = שימוש כבסיס; lab = מעבדה; arrangement = עיבוד; processor = מעבד
// (CPU stays Latin where the key writes CPU); processing = עיבוד; fact = עובדה. The root ע-ב-ד is legitimate (Viktor 06.11.2026:
// «Насчёт ע-ב-ד не ставь сторожа. Это легитим.»): the natural word wherever it is the better one. Modern Israeli Hebrew; the
// user is אתה: tips in the masculine singular imperative (בחר, לחץ), buttons and menus the verbal noun (שמירה, יצירת שיר), a
// confirming question the infinitive (למחוק?). No niqqud or cantillation (nothing in U+0591-U+05C7; the ASCII hyphen for the
// maqaf). Latin stays Latin: YuE2, LoRA, VAE, BPM, ABC, WAV, GPU, model and file names, unit symbols, the keys (Ctrl, Shift,
// Esc), the Tsunami Wave by its name. Section tags such as [Chorus] are never translated, nor made keys. Straight quotes "…" read
// the same in RTL. A path or a sequence in a sentence takes ← in Hebrew (the reading runs leftward: מנוע ← ברירות מחדל); → stays
// where the line reads left to right (a key's ← →, a number's change inside Latin).
