"How strongly: subtle, or normal for a sharper voice.": "באיזו עוצמה: עדין, או רגיל לקול חד יותר.",
"Retune from 440 to 432 Hz (pitch and tempo together). Off keeps 440 Hz, for the public.": "כיוון מחדש מ-440 ל-432 Hz (גובה הצליל והטמפו יחד). כבוי משאיר 440 Hz, לקהל הרחב.",
"Brings the song to the loudness below: measured first, then set in a second pass. Off: the level stays as it came.": "מביא את השיר לעוצמת השמע שלמטה: קודם מדידה, ואז קביעה במעבר שני. כבוי: הרמה נשארת כמו שהגיעה.",
"Loudness": "עוצמת שמע",
"The ceiling for the peaks between samples. −1 leaves room for the MP3 and AAC encoders, which add peaks of their own.": "התקרה לשיאים שבין הדגימות. −1 משאיר מקום למקודדי MP3 ו-AAC, שמוסיפים שיאים משלהם.",
"Also an MP3 at 320 kbps, beside the WAV and the FLAC.": "גם MP3 ב-320 kbps, לצד ה-WAV וה-FLAC.",
"also MP3": "גם MP3",
"What is upscaled: the take, or any file made from it but an upscaled one.": "מה עובר אפסקייל: הטייק, או כל קובץ שנוצר ממנו חוץ מקובץ שכבר עבר אפסקייל.",
