"How many versions to draw: they differ only by the noise, and each takes as long as the first. Two let you pick by ear.": "כמה גרסאות לצייר: הן נבדלות רק ברעש, וכל אחת לוקחת זמן כמו הראשונה. שתיים מאפשרות לך לבחור לפי האוזן.",
