"Strength": "עוצמה",
"How much of the frame ripple to divide out. Viktor's ear: 100 % thinned the opening, 80 % was right.": "כמה מאדוות הפריימים להוציא. האוזן של ויקטור: 100 % דילל את הפתיחה, 80 % היה בדיוק נכון.",
