"How wide the adapter's change is: 16 for one voice or instrument, 32 for a style, 64 for many voices, 128 at most.": "כמה רחב השינוי של המתאם: 16 לקול או לכלי אחד, 32 לסגנון, 64 לקולות רבים, 128 לכל היותר.",
"Whether the music half learns (the part that writes the song's tokens), and how hard its lesson pulls against the anchor: 0 leaves it as the base, a timbre only; raise it for diction and style. What counts is the anchor's share of it, not its size.": "האם חצי המוזיקה לומד (החלק שכותב את הטוקנים של השיר), וכמה חזק השיעור שלו מושך נגד העוגן: 0 משאיר אותו כמו הבסיס, גוון בלבד; הרם אותו בשביל דיקציה וסגנון. מה שקובע הוא החלק של העוגן ממנו, לא הגודל שלו.",
"Pulls the music half back toward the base model, so it keeps what the set does not show. Read it as a share of the AR weight: a tenth lets it move, as much as the weight holds it near the base. Nothing at AR weight 0.": "מושך את חצי המוזיקה חזרה אל מודל הבסיס, כדי שישמור את מה שהסט לא מראה. קרא אותו כחלק ממשקל ה-AR: עשירית נותנת לו לזוז, עוגן בגודל המשקל עצמו מחזיק אותו ליד הבסיס. במשקל AR 0 אין לו השפעה.",
"The music half's learning rate as a share of the one above: the knob that makes it learn faster or slower (0.5: half as fast). It learns a small set by heart quickly.": "קצב הלמידה של חצי המוזיקה כחלק מהקצב שלמעלה: הכפתור שגורם לו ללמוד מהר יותר או לאט יותר (0.5: בחצי מהמהירות). הוא משנן סט קטן בעל פה מהר.",
"How they work ›": "איך הם פועלים ›",
"The music half's three knobs: the guide": "שלושת הכפתורים של חצי המוזיקה: המדריך",
