"As the Studio made it (and the Refiner finished it), no DAW in between.": "כמו שהנפחות יצרה אותה (והמלטש השלים אותה), בלי DAW באמצע.",
"As the Studio made it (and the Refiner finished it), no DAW in between. The take in hand:": "כמו שהנפחות יצרה אותה (והמלטש השלים אותה), בלי DAW באמצע. הטייק שביד:",
"Open a take, play one, or check one in the Librarian: its WAV, FLAC and MP3 come here.": "פתח טייק, נגן אחד או סמן אחד בספרן: ה-WAV, ה-FLAC וה-MP3 שלו יופיעו כאן.",
"Into your DAW": "אל ה-DAW שלך",
"experimental": "ניסיוני",
