"(the mix, every stem, the score as notes, the sections as markers: Waveform 14, Bitwig, Studio One, Cubase); both also in a take’s menu → Download. Waveform: 14 or newer.": "(המיקס, כל סטם, הפרטיטורה כתווים, הקטעים כסמנים: Waveform 14, Bitwig, Studio One, Cubase); שניהם גם בתפריט של טייק ← \"הורדה\". Waveform: גרסה 14 ומעלה.",
"Packing…": "אורז…",
"60 days of evaluation with every function, then a licence: $60 for personal use or a small business": "60 ימי ניסיון עם כל הפונקציות, ואז רישיון: $60 לשימוש אישי או לעסק קטן",
"Waveform Free 14 or newer: free, no track or export limits; it opens the Studio's DAWproject (File > Import Other > Import a DAWproject file). Waveform 13 is not supported": "Waveform Free 14 ומעלה: חינמי, בלי הגבלות על רצועות או ייצוא; פותח את ה-DAWproject של הנפחות (File > Import Other > Import a DAWproject file). Waveform 13 אינו נתמך",
"30 days without limits after signing up, then Essentials $99, Producer $199 or Studio $399 (bitwig.com, 03.10.2026); opens the Studio's DAWproject: the mix, the stems, the score as notes, the sections as markers": "30 יום בלי הגבלות אחרי הרשמה, ואז Essentials ב-$99, Producer ב-$199 או Studio ב-$399 (bitwig.com, 03.10.2026); פותח את ה-DAWproject של הנפחות: המיקס, הסטמים, הפרטיטורה כתווים, הקטעים כסמנים",
"reaper.fm/download.php → the Linux x86_64 tarball → unpack it and run ./install-reaper.sh (it goes to /opt/REAPER)": "reaper.fm/download.php ← קובץ ה-tarball של Linux x86_64 ← חלץ אותו והרץ ./install-reaper.sh (הוא מותקן ב-/opt/REAPER)",
"bitwig.com/download: the Ubuntu .deb (sudo apt install ./bitwig-studio-*.deb) or the Flatpak": "bitwig.com/download: קובץ ה-.deb ל-Ubuntu (sudo apt install ./bitwig-studio-*.deb) או ה-Flatpak",
