"Strength on the sound half: the acoustic stage that turns music tokens into sound (0 off, 1 as trained)": "עוצמה על חצי הצליל: השלב האקוסטי שהופך טוקני מוזיקה לצליל (0 כבוי, 1 כמו באימון)",
"green to {0}, amber to {1}, red beyond": "ירוק עד {0}, כתום עד {1}, אדום מעבר לזה",
"This file has no music half": "לקובץ הזה אין חצי מוזיקה",
"This file has no sound half": "לקובץ הזה אין חצי צליל",
"{0} Music strength": "{0}: עוצמת מוזיקה",
