"Its trigger word is in the style": "מילת ההפעלה שלו נמצאת בסגנון",
"Not in loras/ any more": "כבר לא ב-loras/",
"No .safetensors files in the app's loras/ folder.": "אין קבצי .safetensors בתיקייה loras/ של האפליקציה.",
"No LoRAs found. Put .safetensors files (or folders, or links to them) in the app's loras/ folder.": "לא נמצאו LoRA. שים קבצי .safetensors (או תיקיות, או קישורים אליהם) בתיקייה loras/ של האפליקציה.",
"{0} is no longer in loras/ and will be left out.": "{0} כבר לא ב-loras/ ולא ייכלל.",
"{0} was trained in Direct mode.": "{0} אומן במצב ישיר.",
"{0} was trained with a score ({1} mode).": "{0} אומן עם פרטיטורה (מצב {1}).",
"⚠ {0}: {1} on the music half is past its limit {2}: the score tends to fail after 70-200 tokens.": "⚠ {0}: {1} על חצי המוזיקה חורג מהגבול שלו {2}: הפרטיטורה נוטה להישבר אחרי 70-200 טוקנים.",
"⚠ {0}: {1} on the sound half is past its limit {2}.": "⚠ {0}: {1} על חצי הצליל חורג מהגבול שלו {2}.",
"⚠ {0} plans instrumental scores: at {1} with words to sing, the score loses its vocal line (measured at 1.00: 1 note in 127 vocal bars, the music looping). Keep it low, 0.3–0.5, for a sung song.": "⚠ {0} מתכנן פרטיטורות אינסטרומנטליות: ב-{1} עם מילים לשירה, הפרטיטורה מאבדת את קו השירה (נמדד ב-1.00: תו 1 ב-127 תיבות שירה, והמוזיקה נתקעת בלופ). לשיר מושר השאר אותו נמוך, 0.3–0.5.",
"{#0} stacked: their changes add up.": "מונחים זה על זה: {0}; השינויים שלהם מצטברים.",
"⚠ The music half carries {0} together, past the shared ceiling {1}: runs this heavy wrote broken scores every time (measured). Lower some, or take one off the music half.": "⚠ חצי המוזיקה נושא יחד {0}, מעל התקרה המשותפת {1}: הרצות כבדות כאלה כתבו פרטיטורות שבורות בכל פעם (נמדד). הורד חלק מהם, או הוצא אחד מחצי המוזיקה.",
