"The older official decoder. The published benchmark scores were made with it. Less clean than Standard; some hear it as more musical. Same encoder, only the decoder differs.": "המפענח הרשמי הישן. ציוני הבנצ'מרק שפורסמו נוצרו איתו. פחות נקי מ\"סטנדרטי\"; יש ששומעים אותו כמוזיקלי יותר. אותו מקודד, רק המפענח שונה.",
"A community weight mix of the two official decoders: 2/3 Standard + 1/3 Legacy. Not newly trained. It sits between the clean Standard and the more musical Legacy; the real-audio LoRA's authors suggest it.": "תערובת משקלים של הקהילה משני המפענחים הרשמיים: 2/3 סטנדרטי + 1/3 ישן. היא לא אומנה מחדש. היא יושבת בין הסטנדרטי הנקי לבין הישן המוזיקלי יותר; המחברים של ה-LoRA real-audio ממליצים עליה.",
