"It takes a GPU of its own for hours; a set without its latent cache gets one first (a second or two a track).": "הוא תופס GPU משלו לשעות; סט בלי מטמון לטנטי מקבל אותו קודם (שנייה-שתיים לרצועה).",
"It takes a GPU of its own for hours; the first run also fetches Comfy-Org’s YuE2 weights.": "הוא תופס GPU משלו לשעות; ההרצה הראשונה גם מורידה את משקלי YuE2 של Comfy-Org.",
"Training may take GPU{0}, the Studio’s own card: if it does, synthesis waits until the run ends (Engine → GPUs gives training another card).": "האימון עשוי לתפוס את GPU{0}, הכרטיס של הנפחות עצמה: אם כן, הסינתזה ממתינה עד שההרצה תסתיים (מנוע ← GPU נותן לאימון כרטיס אחר).",
"Start training": "התחלת אימון",
"Training {0}": "מאמן את {0}",
"Listener": "מאזין",
"drafts each track’s style from what it hears; a draft, read and correct it": "מנסח טיוטת סגנון לכל רצועה לפי מה שהוא שומע; זו טיוטה, קרא ותקן אותה",
"Trigger": "מילת הפעלה",
"Shared line": "שורה משותפת",
"after the track’s tags": "אחרי התגיות של הרצועה",
"the album’s vibe": "הווייב של האלבום",
"Write into the captions": "כתיבה לתוך הכיתובים",
"Listening… {0} / {1}": "מאזין… {0} / {1}",
"Listen to {0}": "האזנה ל-{0}",
"Listen to {0}?": "להאזין ל-{0}?",
"Omni hears 120 s of every track and drafts its style. Drafts heard before are kept aside (styles.DATE.json); the captions change only when you write them.": "Omni שומע 120 s מכל רצועה ומנסח טיוטה של הסגנון שלה. טיוטות קודמות נשמרות בצד (styles.DATE.json); הכיתובים משתנים רק כשאתה כותב אותם.",
"Listen": "האזנה",
"Listening to {0}": "מאזין ל-{0}",
"Write {#0} styles into the captions of {1}?": "לכתוב {0} סגנונות לתוך הכיתובים של {1}?",
"Each first line becomes: {0} The lyrics stay.": "כל שורה ראשונה תהיה: {0} המילים נשארות.",
"Write": "כתיבה",
"{#0} captions written": {"one": "נכתב {0} כיתוב", "two": "נכתבו {0} כיתובים", "other": "נכתבו {0} כיתובים"},
"drafts here by {0}": "הטיוטות כאן מאת {0}",
"The Studio’s trainer is missing {0}:": "למאמן של הנפחות חסר {0}:",
"Comfy-Org's YuE2 {0} weights": "משקלי YuE2 {0} של Comfy-Org",
"the realaudio tokenizer head": "ראש הטוקנייזר realaudio",
"and": "וגם",
"The realaudio tokenizer is missing from": "הטוקנייזר realaudio חסר בנתיב",
"{#0} characters, about {#1} tokens.": "{0} תווים, בערך {1} טוקנים.",
"Style and lyrics together: about {#0} of {#1} tokens.": "סגנון ומילים יחד: בערך {0} מתוך {1} טוקנים.",
"Style and lyrics together: about {#0} of {#1} tokens — too long for a full-length song and score.": "סגנון ומילים יחד: בערך {0} מתוך {1} טוקנים — ארוך מדי לשיר באורך מלא עם פרטיטורה.",
"Unlike the model's training styles:": "שונה מסגנונות האימון של המודל:",
"longer than 1,600 characters (the official examples stop at 999)": "ארוך מ-1,600 תווים (הדוגמאות הרשמיות נעצרות ב-999)",
"{#0} Unicode arrow (→): write -> instead": "{0} חץ Unicode (→): כתוב -> במקומו",
"{#0} Unicode arrows (→): write -> instead": "{0} חיצי Unicode (→): כתוב -> במקומם",
"dynamics marks (never in the official styles)": "סימני דינמיקה (אף פעם לא בסגנונות הרשמיים)",
"{#0} \"Label:\" fields (5 of 110 official styles use any)": "שדות \"Label:\": {0} (רק 5 מתוך 110 הסגנונות הרשמיים משתמשים בהם)",
"{#0} bracket line in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "{0} שורה בסוגריים במילים עם \"Label:\", חץ או סימן p/f (אין כאלה בדוגמאות הרשמיות)",
"{#0} bracket lines in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "{0} שורות בסוגריים במילים עם \"Label:\", חץ או סימן p/f (אין כאלה בדוגמאות הרשמיות)",
"{#0} instruments": {"one": "{0} כלי", "two": "{0} כלים", "other": "{0} כלים"},
"{#0} heard": "נשמעו: {0}",
"{#0} questioned": "בספק: {0}",
"{#0} not identified": "לא זוהו: {0}",
"{#0} not judged yet": "עדיין לא הוערכו: {0}",
"the Librarian does not answer: no probes to play": "הספרן לא עונה: אין ניסויים לנגן",
"{#0} styles": {"one": "{0} סגנון", "two": "{0} סגנונות", "other": "{0} סגנונות"},
"{#0} style": {"one": "{0} סגנון", "two": "{0} סגנונות", "other": "{0} סגנונות"},
"what a probe gave instead of its instrument": "מה שניסוי נתן במקום הכלי שלו",
"Nothing matches.": "שום דבר לא מתאים.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ שם בסגנון הוא בקשה, לא הבטחה. מה ש-▶ A ו-▶ B מנגנים הוא מה ש-YuE2 נותן עבורו, בערך תשע פעמים מתוך עשר.",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "יש ניסויים מעולים, ו-A ו-B מסכימים, ובכל זאת הכלי אינו זה שהתבקש: סמוך על האוזן, לא על השם.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "מה ש-YuE2 התבקש לנגן, כלי אחד או סגנון אחד בכל פעם, בניסויים של שתי דקות (דקה אחת לראשונים), שני זרעים לכל אחד, A ו-B.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "כלי מעצב את הסגנון של היצירה כולה: כשקוראים לו בשם, גם העיבוד זז. פצפוץ או רשרוש נייר, כמו בתקליט שחוק, הוא זרע לא מוצלח: צור אותו שוב עם זרע אחר.",
