"Drag: the form takes 55 to 70 % of the width; below 55 the takes take 60 % and the form one column · double-click: the default": "גרור: הטופס תופס 55 עד 70 % מהרוחב; מתחת ל-55 הטייקים תופסים 60 % והטופס עמודה אחת · לחיצה כפולה: ברירת המחדל",
