"Loading the Sound Heresy": "טוען את כפירת הצליל",
"Artwork for “{0}” already waits in the queue for a card": "העטיפה ל-\"{0}\" כבר ממתינה בתור לכרטיס",
"Artwork for “{0}” is being drawn already": "העטיפה ל-\"{0}\" כבר מצוירת",
"Artwork for “{0}” waits in the queue for a card with room; it starts by itself (Engine → GPUs says which card does what)": "העטיפה ל-\"{0}\" ממתינה בתור לכרטיס עם מקום; היא מתחילה מעצמה (מנוע ← כרטיסי GPU אומר איזה כרטיס עושה מה)",
"Artwork for “{0}” waits in the queue: {1}. It starts by itself when a card has room": "העטיפה ל-\"{0}\" ממתינה בתור: {1}. היא מתחילה מעצמה כשיש מקום בכרטיס",
"Artwork waits for a card…": "העטיפה ממתינה לכרטיס…",
