"The phonetic hand: stress marks (U+0301), ayins inside Russian words (a soft о/а), Latin letters inside Russian words (a hard o)": "היד הפונטית: סימני הטעמה (U+0301), עיינים בתוך מילים רוסיות (о/а רכה), אותיות לטיניות בתוך מילים רוסיות (o קשה)",
