"about a minute": "בערך דקה",
"about {0} min": "בערך {0} min",
"1 picture · {0} on one card": "1 תמונה · {0} בכרטיס אחד",
"{#0} pictures · {1} on one card": {"one": "{0} תמונה · {1} בכרטיס אחד", "two": "{0} תמונות · {1} בכרטיס אחד", "other": "{0} תמונות · {1} בכרטיס אחד"},
"pick a shape": "בחר צורה",
