"{0} · guidance {1}": "{0} · הנחיה {1}",
"With Lightning, Karras, Exponential and KL optimal can paint the subject twice: Simple, Beta, Beta 57, SGM uniform or Bong tangent keep it whole.": "עם Lightning, Karras, Exponential ו-KL optimal עלולים לצייר את הנושא פעמיים: Simple, Beta, Beta 57, SGM uniform או Bong tangent שומרים אותו שלם.",
"Without Lightning, Euler SDE paints Qwen soft and hazy: Euler, ER-SDE or RES keep the detail.": "בלי Lightning, Euler SDE מצייר את Qwen רך ומעורפל: Euler, ER-SDE או RES שומרים על הפרטים.",
"picture {#0} of {#1} · step {#2} / {#3} · {#4}%": "תמונה {0} מתוך {1} · צעד {2} / {3} · {4}%",
