"1 picture · {#0} s": "1 תמונה · {0} s",
"{#0} pictures · {#1} s": {"one": "{0} תמונה · {1} s", "two": "{0} תמונות · {1} s", "other": "{0} תמונות · {1} s"},
"a card with room": "כרטיס עם מקום",
"no card can take this now": "אף כרטיס לא יכול לקחת את זה עכשיו",
