"Again": "שוב",
"To the form": "אל הטופס",
"Its prompt, shapes, variations and seed back in the form above": "הפרומפט, הצורות, הווריאציות והזרע שלו חוזרים לטופס שלמעלה",
"The same prompt and shapes once more, from a new seed": "אותו פרומפט ואותן צורות פעם נוספת, מזרע חדש",
"The same picture upscaled once more": "אותה תמונה באפסקייל פעם נוספת",
"The run and its pictures to the trash (the Studio's trash/artist/)": "ההרצה והתמונות שלה לפח (ה-trash/artist/ של הנפחות)",
"Off the queue": "הוצאה מהתור",
"Not kept: the content filter flagged it": "לא נשמרה: מסנן התוכן סימן אותה",
"Look at it": "צפייה",
"Download the picture (PNG, full size)": "הורדת התמונה (PNG, גודל מלא)",
"Set as cover": "הגדרה כעטיפה",
"Pick a take on the right to give it this cover": "בחר טייק מימין כדי לתת לו את העטיפה הזאת",
"A cover is square: this one is for a video or a short": "עטיפה היא מרובעת: זו מיועדת לווידאו או לשורט",
"This picture becomes the cover of “{0}”": "התמונה הזאת הופכת לעטיפה של \"{0}\"",
"This picture becomes the cover of “{0}” (its cover now is kept beside it)": "התמונה הזאת הופכת לעטיפה של \"{0}\" (העטיפה הנוכחית שלו נשמרת לידה)",
"Its prompt, seed and shape back in the form": "הפרומפט, הזרע והצורה שלה חוזרים לטופס",
"Paint from this picture: it becomes the form's reference": "ציור מהתמונה הזאת: היא הופכת לייחוס של הטופס",
"Compare it with another: pick that one in the library, then a divider between them": "השוואה עם תמונה אחרת: בחר אותה בספרייה, ואז מפריד ביניהן",
"Compare…": "השוואה…",
"Over the whole page: ← → walk the pictures, Esc closes": "על כל הדף: ← → מדפדפים בין התמונות, Esc סוגר",
"Over the page": "מעל הדף",
"This picture to the trash: the library's Trash brings it back": "התמונה הזאת לפח: הפח של הספרייה מחזיר אותה",
"Make it 2K or 4K (its long side 2560 or 3840) with an upscaler from models/artist/upscalers/ (ESRGAN, DAT, HAT, SPAN…): a run of its own": "הגדלה ל-2K או ל-4K (הצד הארוך 2560 או 3840) עם אפסקיילר מ-artwork/upscalers/ (ESRGAN, DAT, HAT, SPAN…): הרצה משלה",
"Upscale…": "אפסקייל…",
"Look at it over the page": "צפייה מעל הדף",
"The picture picked in the library shows here, with its run; a run being painted develops here.": "התמונה שנבחרה בספרייה מוצגת כאן, עם ההרצה שלה; הרצה שמצוירת מתפתחת כאן.",
"Star it": "סימון בכוכב",
"Unstar": "הסרת הכוכב",
"Starred: ☆ takes the star off": "מסומן בכוכב: ☆ מסיר את הכוכב",
"Star it: the gallery's ★ shows the starred": "סימון בכוכב: ה-★ של הגלריה מציג את המסומנים בכוכב",
"The picture": "התמונה",
"Gallery": "גלריה",
"Each press of Draw with its prompt, seed and pictures, the newest on top": "כל לחיצה על \"ציור\" עם הפרומפט, הזרע והתמונות שלה, החדשה ביותר למעלה",
"Every picture of every run in one grid, the newest first: filter by shape or by star, three sizes": "כל תמונה של כל הרצה ברשת אחת, החדשות קודם: סינון לפי צורה או לפי כוכב, שלושה גדלים",
"The runs in the trash (the Studio's trash/artist/), the newest first: each comes back with Restore": "ההרצות בפח (ה-trash/artist/ של הנפחות), החדשות קודם: כל אחת חוזרת עם \"שחזור\"",
"How to show them": "איך להציג אותן",
"Which pictures": "אילו תמונות",
"Their size": "הגודל שלהן",
"Starred": "מסומנות בכוכב",
"The starred pictures": "התמונות המסומנות בכוכב",
"No starred picture yet: ☆ on a picture stars it.": "עדיין אין תמונה מסומנת בכוכב: ☆ על תמונה מסמן אותה בכוכב.",
"No picture of this shape yet.": "עדיין אין תמונה בצורה הזאת.",
