"Checkpoints for the extra decoders and the sliders, made into GGUF here": "צ'קפוינטים למפענחים הנוספים ולסליידרים, שהומרו כאן ל-GGUF",
"LoRAs: the Kit's library and Ruach Studio's own": "LoRA: הספרייה של ה-Kit, וה-LoRA של נפחות רוח עצמה",
"M-A-P's YuE2 as GGUF (Serveurperso/YuE2-GGUF): Compute chooses between those here": "YuE2 של M-A-P בתור GGUF (Serveurperso/YuE2-GGUF): \"חישוב\" בוחר בין אלה שכאן",
"M-A-P's YuE2 as GGUF": "YuE2 של M-A-P בתור GGUF",
"the whole model; on a card older than Ampere (an RTX 20xx, a Quadro RTX) it runs without its tensor cores, slower than Q8_0": "המודל המלא; על כרטיס ישן מ-Ampere (RTX 20xx, Quadro RTX) הוא רץ בלי ליבות הטנזור שלו, לאט יותר מ-Q8_0",
"The whole model; on a card older than Ampere (an RTX 20xx, a Quadro RTX) it runs without its tensor cores, slower than Q8_0": "המודל המלא; על כרטיס ישן מ-Ampere (RTX 20xx, Quadro RTX) הוא רץ בלי ליבות הטנזור שלו, לאט יותר מ-Q8_0",
"Style listener": "מאזין הסגנון",
"Qwen2.5-Omni-7B: hears the songs of a training set and writes each one's style tags; the GGUF ones run through llama.cpp (vendor/llama.cpp, built by you)": "Qwen2.5-Omni-7B: מאזין לשירים של סט אימון ורושם לכל אחד את תגיות הסגנון שלו; גרסאות ה-GGUF רצות דרך llama.cpp (vendor/llama.cpp, שאתה בונה)",
"{#0} GB of VRAM when it listens": "{#0} GB של VRAM כשהוא מאזין",
"{#0} GB of VRAM when it listens: a 24 GB card": "{#0} GB של VRAM כשהוא מאזין: כרטיס של 24 GB",
"less when some of it is here": "פחות כשחלק ממנו כבר כאן",
"Less when some of it is here": "פחות כשחלק ממנו כבר כאן",
"Qwen painters": "ציירי Qwen",
"the Artist's Qwen-Image painters: 2512 with Lightning's 8 steps (Apache-2.0: its parts from Qwen, the transformer as GGUF) and 2.1 (Qwen's research licence)": "ציירי Qwen-Image של הצייר: 2512 עם 8 הצעדים של Lightning (Apache-2.0: החלקים שלו מ-Qwen, הטרנספורמר בתור GGUF) ו-2.1 (רישיון המחקר של Qwen)",
"the Artist's Qwen-Image painters": "ציירי Qwen-Image של הצייר",
"for a card of 16 GB (below 20 GB its text encoder reads the prompt on the processor: 17 GB of RAM); half a minute a picture on a 3090; less when some of it is here": "לכרטיס של 16 GB (מתחת ל-20 GB מקודד הטקסט שלו קורא את הפרומפט על המעבד: 17 GB של RAM); חצי דקה לתמונה על 3090; פחות כשחלק ממנו כבר כאן",
"For a card of 16 GB (below 20 GB its text encoder reads the prompt on the processor: 17 GB of RAM); half a minute a picture on a 3090; less when some of it is here": "לכרטיס של 16 GB (מתחת ל-20 GB מקודד הטקסט שלו קורא את הפרומפט על המעבד: 17 GB של RAM); חצי דקה לתמונה על 3090; פחות כשחלק ממנו כבר כאן",
"For a card of 24 GB; less when some of it is here": "לכרטיס של 24 GB; פחות כשחלק ממנו כבר כאן",
"Under Qwen's research licence: research and evaluation only, not for commercial use (a cover for a song that is sold is commercial use); a card of 24 GB, about two minutes a picture": "תחת רישיון המחקר של Qwen: למחקר ולהערכה בלבד, לא לשימוש מסחרי (עטיפה לשיר שנמכר היא שימוש מסחרי); כרטיס של 24 GB, בערך שתי דקות לתמונה",
"LoRA trainer's base": "הבסיס של מאמן ה-LoRA",
"Comfy-Org/YuE2 for the Trainer, with Mothersuperior's tokenizer head and m-a-p's MERT-v2-FullSong (the set's latent cache hears with it)": "Comfy-Org/YuE2 למאמן, עם ראש הטוקנייזר של Mothersuperior ו-MERT-v2-FullSong של m-a-p (מטמון הלטנטים של הסט שומע איתו)",
"Trains on unquantized weights; MERT-v2-FullSong's 2.5 GB among them, less when it is here": "מתאמן על משקלים ללא קוונטיזציה; ה-2.5 GB של MERT-v2-FullSong ביניהם, פחות כשהוא כבר כאן",
"For a smaller card; MERT-v2-FullSong's 2.5 GB among them, less when it is here": "לכרטיס קטן יותר; ה-2.5 GB של MERT-v2-FullSong ביניהם, פחות כשהוא כבר כאן",
"The Artist paints with it.": "הצייר מצייר איתו.",
