"A folder that is there already; {0} goes into it as «{1}». On the same disk it is renamed at once; on another it is copied, checked file by file, then the link is switched, and the old copy stays, renamed, for you to remove after a look.": "תיקייה שכבר קיימת; {0} נכנס אליה בתור \"{1}\". באותו דיסק השם שלו משתנה מיד; בדיסק אחר הוא מועתק, נבדק קובץ אחר קובץ, ואז הקישור מוחלף, והעותק הישן נשאר, בשם אחר, כדי שתסיר אותו אחרי שתבדוק.",
