"The lines' numbers in the box, as a code editor shows them (Alt+K marks a line, Alt+J goes to the next mark)": "מספרי השורות בשדה, כמו שעורך קוד מציג אותם (Alt+K מסמן שורה, Alt+J עובר לסימון הבא)",
"Marks: {0}": "סימונים: {0}",
"Marked lines: Alt+K marks the cursor's line or unmarks it, Alt+J goes to the next, Alt+Shift+J to the one before, Alt+Shift+K clears them. Press to go to the next one.": "שורות מסומנות: Alt+K מסמן את שורת הסמן או מבטל את הסימון, Alt+J עובר לבאה, Alt+Shift+J לקודמת, Alt+Shift+K מנקה אותן. לחץ כדי לעבור לבאה.",
"Press to go to the next one.": "לחץ כדי לעבור לבא.",
"line {0}: {1}": "שורה {0}: {1}",
"Tags not closed or astray: {0}": "תגיות לא סגורות או לא במקומן: {0}",
"Round brackets to look at: {0}": "סוגריים עגולים לבדיקה: {0}",
"Stress marks off a vowel: {0}": "סימני הטעמה שלא על תנועה: {0}",
"Words with two stress marks: {0}": "מילים עם שני סימני הטעמה: {0}",
"A stress mark (U+0301) stands right after the vowel it stresses. Press to go to the next one.": "סימן הטעמה (U+0301) עומד מיד אחרי התנועה שהוא מטעים. לחץ כדי לעבור לבא.",
"One word, two stress marks: meant, or a slip? Press to go to the next one.": "מילה אחת, שני סימני הטעמה: בכוונה, או טעות? לחץ כדי לעבור לבאה.",
"{0} is a spacing accent, not the stress mark (U+0301 after the vowel)": "{0} הוא תו הטעמה עצמאי, לא סימן ההטעמה (U+0301 אחרי התנועה)",
"at the line's start": "בתחילת השורה",
