"after a space": "אחרי רווח",
"a second mark on {0}": "סימן שני על {0}",
"on {0}, not a vowel": "על {0}, שאינו תנועה",
"after {0}": "אחרי {0}",
"two marks in {0}": "שני סימנים ב-{0}",
"Consonant beats: {0}": "פעמות עיצורים: {0}",
"Beats no vowel carries, counted with the syllables in each line's bar (drawn lighter): a word with no vowel (с, в, к, з, й, ў) and a stop closed against an affricate inside a word (глу-п-цо́в)": "פעמות שאף תנועה לא נושאת, נספרות עם ההברות בפס של כל שורה (בגוון בהיר יותר): מילה בלי תנועה (с, в, к, з, й, ў) ועיצור סותם שנסגר מול עיצור מחוכך בתוך מילה (глу-п-цо́в)",
"The lyrics editor's keys, as in mcedit:\nAlt+K  mark the cursor's line (again: unmark it)\nAlt+J  the next mark · Alt+Shift+J the one before\nAlt+O  clear the marks (Alt+Shift+K too)\nAlt+L  go to a line by its number\nCtrl+Y  delete the line\nAlt+↑ Alt+↓  move the line, or the lines selected\n[ at a line's start, or Ctrl+Space  the section tags\nCtrl+F  find in the box\nAlt+I  the instruments' and styles' cheat-sheet\nCtrl+Z  take a change back": "המקשים של עורך המילים, כמו ב-mcedit:\nAlt+K  סימון שורת הסמן (שוב: ביטול הסימון)\nAlt+J  הסימון הבא · Alt+Shift+J הקודם\nAlt+O  ניקוי הסימונים (גם Alt+Shift+K)\nAlt+L  מעבר לשורה לפי המספר שלה\nCtrl+Y  מחיקת השורה\nAlt+↑ Alt+↓  הזזת השורה, או השורות שנבחרו\n[ בתחילת שורה, או Ctrl+Space  תגיות הקטעים\nCtrl+F  חיפוש בשדה\nAlt+I  השליף של הכלים והסגנונות\nCtrl+Z  ביטול שינוי",
