"TEST: none of the 110 official examples writes it, so YuE2 may sing it as words or pass it by. Listen before you keep it.": "ניסיוני: אף אחת מ-110 הדוגמאות הרשמיות לא כותבת אותה, אז YuE2 עלול לשיר אותה כמילים או לדלג עליה. האזן לפני שתשאיר אותה.",
