"Render this take's sound again with this VAE: it was made before takes kept their latents, so it takes as long as its sound did\n{0}": "רינדור מחדש של הצליל של הטייק הזה עם ה-VAE הזה: הוא נוצר לפני שטייקים שמרו את הלטנטים שלהם, אז זה לוקח אותו זמן שלקח הצליל שלו\n{0}",
