"How many steps the sound solver takes to turn the music tokens into audio (flow matching, midpoint method). 32 is the release setting; 160 is the ceiling.": "כמה צעדים פותר הצליל עושה כדי להפוך את טוקני המוזיקה לאודיו (flow matching, שיטת midpoint). 32 הוא הערך של הגרסה הרשמית; 160 היא התקרה.",
"Each step runs the sound model twice over the whole song, so 64 steps make this stage take twice as long as 32; the music itself (melody, words, length) is already fixed by then and does not change.": "כל צעד מריץ את מודל הצליל פעמיים על כל השיר, כך ש-64 צעדים הופכים את השלב הזה לארוך פי שניים מ-32; המוזיקה עצמה (מנגינה, מילים, אורך) כבר קבועה עד אז ולא משתנה.",
"Fewer steps (8–16) are quicker drafts. Whether 64 sounds better than 32 has not been published: to hear it, re-render one take's sound at both settings.": "פחות צעדים (8–16) הם טיוטות מהירות יותר. אם 64 נשמע טוב יותר מ-32 עוד לא פורסם: כדי לשמוע, רנדר מחדש את הצליל של טייק אחד בשתי ההגדרות.",
"Decode this take again with this VAE: its own sound, another decoder, in seconds": "פענוח מחדש של הטייק הזה עם ה-VAE הזה: הצליל שלו עצמו, מפענח אחר, תוך שניות",
"Render this take's sound again with this VAE: it was made before takes kept their latents, so it takes as long as its sound did": "רינדור מחדש של הצליל של הטייק הזה עם ה-VAE הזה: הוא נוצר לפני שטייקים שמרו את הלטנטים שלהם, אז זה לוקח אותו זמן שלקח הצליל שלו",
