"Redo (Ctrl+Shift+Z)": "ביצוע חוזר (Ctrl+Shift+Z)",
"The frame and the picture in sight (F)": "המסגרת והתמונה בתצוגה (F)",
"Tools": "כלים",
"Move and scale the picture: drag it, or a corner (V); arrows nudge it": "הזזה ושינוי גודל של התמונה: גרור אותה, או פינה (V); החיצים מזיזים אותה מעט",
"Paint the mask: what it covers is repainted (B)": "ציור המסכה: מה שהיא מכסה מצויר מחדש (B)",
