"The picture's opacity on the board": "האטימות של התמונה על הלוח",
"The picture's opacity on the board (only here: the painting takes it whole)": "האטימות של התמונה על הלוח (רק כאן: הציור לוקח אותה במלואה)",
"Its place in this frame": "המיקום שלה במסגרת הזאת",
"Width": "רוחב",
"How it is painted": "איך היא מצוירת",
"V move · B brush · E eraser · H or Space the board · [ ] the brush · wheel zoom · Alt+wheel the picture's size · F in sight · 1 2 3 the shapes · Ctrl+Z": "V הזזה · B מכחול · E מחק · H או Space הלוח · [ ] המכחול · גלגלת זום · Alt+גלגלת גודל התמונה · F בתצוגה · 1 2 3 הצורות · Ctrl+Z",
"The picture {0} px in the frame's {1}, ×{2} its own size": "התמונה {0} px במסגרת של {1}, ×{2} מהגודל המקורי שלה",
"painted from the picture": "מצויר מהתמונה",
"repainted by the mask": "מצויר מחדש לפי המסכה",
"painted around the picture": "מצויר סביב התמונה",
"painted around, and by the mask": "מצויר מסביב, ולפי המסכה",
"Get painters and adapters…": "הורדת ציירים ומתאמים…",
"The painters, the Qwen fine-tunes and the adapters the Studio can fetch for the Artist, each with its size, here or not: from the Studio's models repository and from their makers": "הציירים, הפיינטיונים של Qwen והמתאמים שהנפחות יכולה להוריד בשביל הצייר, כל אחד עם הגודל שלו, ואם הוא כבר כאן: ממאגר המודלים של הנפחות ומהמפתחים שלהם",
"Painters and adapters to fetch": "ציירים ומתאמים להורדה",
"Asking the lab what is here…": "שואל את המעבדה מה יש כאן…",
"Fetching:": "מוריד:",
"The Artist offers it under Fine-tune.": "הצייר מציע אותו תחת \"פיינטיון\".",
"The Artist's LoRA library shows them under their painters.": "ספריית ה-LoRA של הצייר מציגה אותם תחת הציירים שלהם.",
"Qwen fine-tunes": "פיינטיונים של Qwen",
"Artist's adapters": "המתאמים של הצייר",
"the fp8 fine-tunes of Qwen-Image 2512 for finished realism (a card of 24 GB), from {0}, shared there by their authors' leave (Civitai: share and sell)": "הפיינטיונים ב-fp8 של Qwen-Image 2512 לריאליזם מוגמר (כרטיס של 24 GB), מ-{0}, משותפים שם ברשות המחברים שלהם (Civitai: שיתוף ומכירה)",
"and Qwen-Image 2512's parts (17.7 GB) when they are not here": "וחלקי Qwen-Image 2512 (17.7 GB) כשהם לא כאן",
"seven adapters": "שבעה מתאמים",
"Keep the canvas and draw the shapes picked in the form (Ctrl+Enter)": "שמירת הקנבס וציור הצורות שנבחרו בטופס (Ctrl+Enter)",
"Its trigger words into the prompt:": "מילות ההפעלה שלו לתוך הפרומפט:",
"Its trigger words out of the prompt:": "מילות ההפעלה שלו מחוץ לפרומפט:",
"{#0} on · {#1} / {#2}": "{#0} בהרצה · {#1} / {#2}",
"Made for {0}: it reaches none of this painter's layers": "נוצר בשביל {0}: הוא לא מגיע לאף שכבה של הצייר הזה",
"Eight adapters at most in the list: take one off first": "שמונה מתאמים לכל היותר ברשימה: הסר אחד קודם",
"Four in the run at most: this one came in muted (right-click: mute another and bring it in)": "ארבעה בהרצה לכל היותר: זה נכנס מושתק (לחיצה ימנית: השתק אחר והכנס את זה)",
"Four in the run at most: mute one first": "ארבעה בהרצה לכל היותר: השתק אחד קודם",
