"To the art's trash…": "לפח התמונות…",
"What it is made for, its trigger words, its file and what its trainer wrote into it": "בשביל מה הוא נוצר, מילות ההפעלה שלו, הקובץ שלו ומה שכתב בו מי שאימן אותו",
"When an adapter comes into the run its trigger words are added to the prompt, and taken out when it leaves": "כשמתאם נכנס להרצה, מילות ההפעלה שלו נוספות לפרומפט, ומוסרות כשהוא יוצא",
"Its SHA-256 alone goes to civitai.com: its name, base model and trigger words come back": "רק ה-SHA-256 שלו נשלח ל-civitai.com: השם שלו, מודל הבסיס ומילות ההפעלה חוזרים",
