"An upscale in passes, as Viktor's ComfyUI stack: each pass a model and a size of the picture's own": "אפסקייל בכמה מעברים, כמו הסטאק של ComfyUI של ויקטור: בכל מעבר מודל וגודל ביחס לגודל המקורי של התמונה",
"Passes…": "מעברים…",
"Passes": "מעברים",
"Each pass runs its model over the picture as it stands and lands at the picture's own size × its factor (each factor the picture's, not the pass before's): Viktor's ComfyUI stack, CR Apply Multi Upscale. Then the long side, then the colours put back to the picture's.": "כל מעבר מריץ את המודל שלו על התמונה כפי שהיא ונוחת בגודל המקורי של התמונה × המקדם שלו (כל מקדם ביחס לתמונה, לא למעבר הקודם): הסטאק של ComfyUI של ויקטור, CR Apply Multi Upscale. אחר כך הצלע הארוכה, ואחר כך הצבעים מוחזרים לצבעי התמונה.",
"Viktor's Qwen 2512 chain (ComfyUI)": "השרשרת של ויקטור ל-Qwen 2512 (ComfyUI)",
