"{#0} takes have these pictures as their covers: take the covers off them too, or leave them? Each take keeps a copy of its own.": {"one": "ל-{#0} טייק התמונות האלה משמשות כעטיפות: להסיר את העטיפות גם ממנו, או להשאיר? לכל טייק יש עותק משלו.", "two": "ל-{#0} טייקים התמונות האלה משמשות כעטיפות: להסיר את העטיפות גם מהם, או להשאיר? לכל טייק יש עותק משלו.", "other": "ל-{#0} טייקים התמונות האלה משמשות כעטיפות: להסיר את העטיפות גם מהם, או להשאיר? לכל טייק יש עותק משלו."},
