"The spectral centroid: where the sound's weight sits at each moment, its brightness; higher is brighter": "הצנטרואיד הספקטרלי: היכן יושב משקל הצליל בכל רגע, הבהירות שלו; ככל שגבוה יותר, כך בהיר יותר",
