"for its style only (Qwen-Image 2.1)": "רק בשביל הסגנון שלה (Qwen-Image 2.1)",
"How the picture is used: painted from (image to image, by the form's painter, as far as How much it may change says); edited by the prompt's words (Qwen-Image 2.1 keeps the scene and changes what the words say); or for its style only (Qwen-Image 2.1 paints the prompt's own scene in the picture's technique, brushwork, palette and light). Qwen-Image 2.1 is under the Qwen Research Licence: research and evaluation only": "איך משתמשים בתמונה: מציירים ממנה (image to image, בצייר שבטופס, ככל ש\"כמה מותר לשנות\" מתיר); עורכים אותה לפי מילות הפרומפט (Qwen-Image 2.1 שומר על הסצנה ומשנה את מה שהמילים אומרות); או רק בשביל הסגנון שלה (Qwen-Image 2.1 מצייר את הסצנה של הפרומפט בטכניקה, במשיכות המכחול, בפלטה ובאור של התמונה). Qwen-Image 2.1 תחת Qwen Research Licence: למחקר ולהערכה בלבד",
"in the picture's style": "בסגנון התמונה",
"edited by words": "נערך במילים",
"The answer reached the output limit: review it carefully, or raise Max tokens.": "התשובה הגיעה למגבלת הפלט: בדוק אותה בעיון, או העלה את \"מקסימום טוקנים\".",
