"A MIDI keyboard of this computer: its keys play here; with Rec on, a key writes a note at the cursor and the cursor steps on": "מקלדת MIDI של המחשב הזה: הקלידים שלה מנגנים כאן; כש-Rec מופעל, קליד כותב תו בסמן והסמן מתקדם",
