"Rec": "Rec",
"The roll into the score in the box: only the lines whose notes or chords changed are written anew, every other line stays as YuE2 wrote it": "הרול לתוך הפרטיטורה שבשדה: רק השורות שהתווים או האקורדים שלהן השתנו נכתבות מחדש, וכל שורה אחרת נשארת כפי ש-YuE2 כתב אותה",
"As YuE2 wrote it": "כפי ש-YuE2 כתב אותה",
"As it stands now": "כפי שהיא עכשיו",
"Click: a note · drag: move, its lower edge: longer · right-click or Delete: away · Shift and keys together: a chord on the cursor's bar · keys A S D F G H J K L ; ' and W E T Y U O P ]: a keyboard and a half, Z X an octave · ←→ a semitone, ↑↓ a step · Tab: the other staff · wheel: time, Ctrl+wheel: closer · F11: the whole screen": "לחיצה: תו · גרירה: הזזה, הקצה התחתון שלו: ארוך יותר · קליק ימני או Delete: הסרה · Shift וקלידים יחד: אקורד בתיבה של הסמן · מקשים A S D F G H J K L ; ' ו-W E T Y U O P ]: מקלדת וחצי, Z X אוקטבה · ←→ חצי טון, ↑↓ צעד · Tab: החמשה השנייה · גלגל: זמן, Ctrl+גלגל: קרוב יותר · F11: מסך מלא",
"a chord: keep Shift and add keys": "אקורד: החזק Shift והוסף קלידים",
"no chord YuE2 reads": "אין אקורד ש-YuE2 קורא",
