"The computer's keys from {0}": "מקשי המחשב מ-{0}",
"This browser gives no MIDI (Chrome and Edge do)": "הדפדפן הזה לא תומך ב-MIDI (Chrome ו-Edge תומכים)",
"MIDI: {0} keyboard(s) listened to": "MIDI: מאזין למקלדות: {0}",
