"MIDI was not allowed by the browser": "הדפדפן לא אישר גישה ל-MIDI",
"One's own MIDI keyboard: the keys it reaches marked over the keyboards (they keep their size); ‹ › move the keys in sight an octave": "מקלדת MIDI משלך: הקלידים שהיא מגיעה אליהם מסומנים מעל המקלדות (הן שומרות על הגודל שלהן); ‹ › מזיזים את הקלידים שבתצוגה באוקטבה",
"Hear the score as YuE2 wrote it": "האזנה לפרטיטורה כפי ש-YuE2 כתב אותה",
"Hear the score as it stands now": "האזנה לפרטיטורה כפי שהיא עכשיו",
"The instruments' melody, as keys": "המנגינה של הכלים, כקלידים",
