"Both at once": "שניהם יחד",
"Piano roll": "פיאנו רול",
"The score in the box as a piano roll: both staves, Vocal and Ins, a note a click; written back into the score line by line, every untouched line as YuE2 wrote it": "הפרטיטורה שבשדה כפיאנו רול: שתי החמשות, Vocal ו-Ins, תו בלחיצה; נכתבת בחזרה לפרטיטורה שורה אחר שורה, וכל שורה שלא נגעו בה כפי ש-YuE2 כתב אותה",
"No score in the box yet: load one, plan one in Full, or import a MIDI file first": "אין עדיין פרטיטורה בשדה: טען אחת, תכנן אחת ב-Full, או ייבא קודם קובץ MIDI",
"The score does not read, so the roll cannot open it:": "הפרטיטורה לא נקראת, ולכן הרול לא יכול לפתוח אותה:",
"The staff in hand": "החמשה שביד",
"The vocal staff in hand: what is sung. Ins stays drawn faint behind it": "חמשת השירה ביד: מה שמושר. Ins נשארת מצוירת חיוורת מאחוריה",
"The instruments' staff in hand: their melody. Vocal stays drawn faint behind it": "חמשת הכלים ביד: המנגינה שלהם. Vocal נשארת מצוירת חיוורת מאחוריה",
"Grid and the length of a new note": "הגריד ואורך התו החדש",
"Give back the last change (Ctrl+Z)": "ביטול השינוי האחרון (Ctrl+Z)",
"Take it again (Ctrl+Shift+Z)": "ביצוע חוזר (Ctrl+Shift+Z)",
"Both staves from the cursor, as plain tones at the score's tempo (Space); a click on the ruler sets the cursor": "שתי החמשות מהסמן, כצלילים פשוטים בטמפו של הפרטיטורה (Space); לחיצה על הסרגל קובעת את הסמן",
"The roll into the score in the box: only the lines whose notes changed are written anew, every other line stays as YuE2 wrote it": "הרול לתוך הפרטיטורה שבשדה: רק השורות שהתווים שלהן השתנו נכתבות מחדש, וכל שורה אחרת נשארת כפי ש-YuE2 כתב אותה",
"Write into the score": "כתיבה לפרטיטורה",
"Close (Esc); what is not written into the score is dropped": "סגירה (Esc); מה שלא נכתב לפרטיטורה הולך לאיבוד",
"Click: a note · drag: move or stretch · right-click or Delete: away · ↑↓ a semitone, Shift an octave · ←→ a step of the grid · Shift+click: pick more · Tab: the other staff": "לחיצה: תו · גרירה: הזזה או מתיחה · קליק ימני או Delete: הסרה · ↑↓ חצי טון, Shift אוקטבה · ←→ צעד של הגריד · Shift+לחיצה: הוספה לבחירה · Tab: החמשה השנייה",
"Written into the score: {0} lines anew, {1} as YuE2 wrote them": "נכתב לפרטיטורה: {0} שורות מחדש, {1} כפי ש-YuE2 כתב אותן",
