"Two seconds from the input: with nothing playing into it, the converter's own noise": "שתי שניות מהכניסה: כששום דבר לא מתנגן לתוכה, זה הרעש של הממיר עצמו",
"A plugin's analog step plays through the output chosen here and records from the input, at this rate.": "שלב אנלוגי של פלאגין מנגן דרך היציאה שנבחרה כאן ומקליט מהכניסה, בקצב הזה.",
"No sound card is seen here.": "לא נראה כאן אף כרטיס קול.",
