"Choose the input first": "בחר קודם את הכניסה",
"Listening to the input for two seconds…": "מאזין לכניסה במשך שתי שניות…",
"The input's floor, RMS / peak dBFS: {0}": "רצפת הרעש של הכניסה, RMS / שיא dBFS: {0}",
"Not measured: {0}": "לא נמדד: {0}",
"no sound card is seen here (/proc/asound has none)": "לא נראה כאן אף כרטיס קול (ב-/proc/asound אין אף אחד)",
"aplay is not here: ALSA's software devices are not listed": "aplay לא נמצא כאן: התקני התוכנה של ALSA לא מוצגים",
"arecord is not here: ALSA's software devices are not listed": "arecord לא נמצא כאן: התקני התוכנה של ALSA לא מוצגים",
"PipeWire / Pulse do not run here (no pactl answer)": "PipeWire / Pulse לא רצים כאן (אין תשובה מ-pactl)",
"JACK does not run here (no jack_lsp)": "JACK לא רץ כאן (אין jack_lsp)",
"the lab reaches the sound devices through sg audio: its service started before the audio group was given": "המעבדה ניגשת להתקני הקול דרך sg audio: השירות שלה עלה לפני שניתנה הקבוצה audio",
"The interface the gateway plays a take out through, to the gear": "הממשק שדרכו השער מוציא טייק אל הציוד",
"The interface the gateway records the gear back from": "הממשק שממנו השער מקליט את הציוד בחזרה",
"The rate both run at: the ones the chosen output and input both take": "הקצב ששניהם רצים בו: אלה שגם היציאה וגם הכניסה שנבחרו מקבלות",
"A 1 kHz tone at −20 dBFS out through the output and back from the input: did it come back, its gain, the noise before it, its THD": "טון 1 kHz ברמה של −20 dBFS יוצא דרך היציאה וחוזר מהכניסה: האם חזר, ההגבר שלו, הרעש שלפניו, ה-THD שלו",
"Loop test": "בדיקת לולאה",
"Choose the output and the input first": "בחר קודם את היציאה ואת הכניסה",
"A 1 kHz tone at −20 dBFS plays through {0} for two seconds. Turn the monitors down if they are on.": "טון 1 kHz ברמה של −20 dBFS יתנגן דרך {0} במשך שתי שניות. הנמך את המוניטורים אם הם דולקים.",
"Play it": "ניגון",
"The tone goes out and comes back…": "הטון יוצא וחוזר…",
