"The loop did not run: {0}": "הלולאה לא רצה: {0}",
"The setup as it is now (the steps' settings and where the nodes stand, never a take's sources) under a name": "התצורה כמו שהיא עכשיו (ההגדרות של השלבים והמקום של הצמתים, אף פעם לא המקורות של טייק) תחת שם",
"Set every step as it was kept under this name": "הגדרת כל שלב כפי שנשמר תחת השם הזה",
