"Set it": "החלה",
"Keep the setup as it is now under this name": "שמירת התצורה הנוכחית תחת השם הזה",
"Delete the profile «{0}»?": "למחוק את הפרופיל \"{0}\"?",
"Profile «{0}» kept": "הפרופיל \"{0}\" נשמר",
"Profile «{0}» set: {1} settings changed": "הפרופיל \"{0}\" הוחל; הגדרות ששונו: {1}",
"Profile «{0}» deleted": "הפרופיל \"{0}\" נמחק",
"The profiles could not be kept: {0}": "לא ניתן היה לשמור את הפרופילים: {0}",
"Clone": "שכפול",
