"The Musician's versions did not come: {0}": "גרסאות המוזיקאי לא הגיעו: {0}",
"too long to compare line by line": "ארוך מדי להשוואה שורה אחר שורה",
"the same": "זהה",
"unchanged lines: {0}": "שורות ללא שינוי: {0}",
"a click picks a version; Ctrl or Shift and a click, a second: their difference": "לחיצה בוחרת גרסה; Ctrl או Shift ולחיצה, גרסה שנייה: ההבדל ביניהן",
"versions: {0}": "גרסאות: {0}",
