"score": "פרטיטורה",
"takes: {0}": "טייקים: {0}",
"Nothing kept under this title yet: every Generate keeps its words here.": "עדיין לא נשמר כלום תחת הכותרת הזאת: כל לחיצה על \"יצירת שיר\" (Generate) שומרת כאן את המילים שלה.",
"Trash ({0})": "פח ({0})",
"Bring back": "שחזור",
"deleted from the library; its words are kept here": "נמחק מהספרייה; המילים שלו שמורות כאן",
"Its title, style, lyrics and score into the Musician's form": "הכותרת, הסגנון, המילים והפרטיטורה שלה אל הטופס של המוזיקאי",
"★ Starred": "★ מסומן בכוכב",
"☆ Star": "☆ סימון בכוכב",
