"The bar grid (G): bars and beats as heard in the take, the cuts, the copies, the loop and a click cling to them; Alt held lets them go. A right-click: twice or half the tempo, where a bar begins, beats a bar, the chord lane": "רשת התיבות (G): תיבות ופעמות כפי שהן נשמעות בטייק; החיתוכים, ההעתקים, הלופ ולחיצה נצמדים אליהן; עם Alt לחוץ הם חופשיים. לחיצה ימנית: טמפו כפול או חצי, היכן מתחילה תיבה, פעמות בתיבה, רצועת האקורדים",
