"The score's chords on the bar grid: a click goes to one, a double-click loops it; the key at the left": "אקורדי הפרטיטורה על רשת התיבות: לחיצה עוברת לאקורד, לחיצה כפולה מלפפת אותו; הסולם משמאל",
