"colons in a run of {0}": "נקודתיים ברצף: {0}",
"the lowest sound and music loss on the held-out tracks (flow {0}, ar_ce {1})": "ההפסד הנמוך ביותר של צליל ומוזיקה ברצועות שהושארו בצד (flow {0}, ar_ce {1})",
"the lowest sound and music loss on the held-out tracks (flow {0})": "ההפסד הנמוך ביותר של צליל ומוזיקה ברצועות שהושארו בצד (flow {0})",
"the lowest sound loss on the held-out tracks (flow {0}, ar_ce {1})": "ההפסד הנמוך ביותר של צליל ברצועות שהושארו בצד (flow {0}, ar_ce {1})",
"the lowest sound loss on the held-out tracks (flow {0})": "ההפסד הנמוך ביותר של צליל ברצועות שהושארו בצד (flow {0})",
"the lowest music loss on the held-out tracks (flow {0}, ar_ce {1})": "ההפסד הנמוך ביותר של מוזיקה ברצועות שהושארו בצד (flow {0}, ar_ce {1})",
"beta": "בטא",
"Beta: we make our songs here every day, and it is all still growing; what it keeps and how it looks may change in a later release.": "בטא: אנחנו יוצרים כאן את השירים שלנו כל יום, והכול עדיין גדל; מה שנשמר ואיך שזה נראה עשויים להשתנות בגרסה עתידית.",
"RS-FW merge": "מיזוג RS-FW",
"YuE2-3B with Ruach Studio's own fine-tune folded in (YuE2-RS-FW, at seven points of its training: epoch x strength): 2.4x0.75 is the Studio's default, the safest; from goldhub/YuE2-RS-Finetunes (CC BY-NC-SA 4.0). Compute chooses it beside m-a-p's backbones; the adapters themselves are not published": "YuE2-3B עם הפיינטיון של נפחות רוח עצמה ממוזג פנימה (YuE2-RS-FW, בשבע נקודות של האימון שלו: אפוק x עוצמה): 2.4x0.75 הוא ברירת המחדל של הנפחות, הבטוח ביותר; מתוך goldhub/YuE2-RS-Finetunes (CC BY-NC-SA 4.0). \"חישוב\" בוחר בו לצד מודלי הבסיס של m-a-p; המתאמים עצמם אינם מתפרסמים",
"The Studio's default": "ברירת המחדל של הנפחות",
