"The tags of the styles here: a click filters the playlist by them, all ticked at once, and what plays with it": "התגיות של הסגנונות כאן: לחיצה מסננת לפיהן את הפלייליסט, כל המסומנות יחד, ואיתו את מה שמתנגן",
"No styles to read tags from here": "אין כאן סגנונות לקרוא מהם תגיות",
