"Archive “{0}”?": "להעביר את \"{0}\" לארכיון?",
"It leaves the tree for Archived (under Out of sight), its sections with it, whole with its takes: they leave All Workspaces and the search, and no new take lands in it. Its ⋯ there brings it back, or sends it to the trash.": "הוא עוזב את העץ אל \"בארכיון\" (תחת \"רחוק מהעין\"), יחד עם המדורים שלו, בשלמותו עם הטייקים שלו: הם יוצאים מ\"כל המרחבים\" ומהחיפוש, ושום טייק חדש לא נוחת בו. ה-⋯ שלו שם מחזיר אותו, או מעביר אותו לפח.",
"Add to a workspace": "הוספה למרחב",
