"Move to a workspace": "העברה למרחב",
"Move the checked into a workspace and out of this one (out of every other in All Workspaces): the tree to choose from": "העברת המסומנים למרחב והוצאתם מהמרחב הזה (ב\"כל המרחבים\": מכל השאר): העץ לבחירה",
