"Equalizer": "אקולייזר",
"Arpeggios": "ארפג'יו",
"Dynamics, soft to loud": "דינמיקה, משקט לחזק",
"The whole keyboard": "כל המקלדת",
"Back to the preset's": "חזרה לערך של הפריסט",
"Mic {0}": "מיקרופון {0}",
"the preset's": "של הפריסט",
"{0} changed": "שונו: {0}",
"Any of Pianoteq's presets, by class and instrument": "כל אחד מהפריסטים של Pianoteq, לפי סוג וכלי",
"A second state to compare: what you set on B leaves A as it was": "מצב שני להשוואה: מה שאתה מגדיר ב-B משאיר את A כפי שהיה",
"Locked by this Pianoteq's edition ({0})": "נעול על ידי המהדורה של Pianoteq הזה ({0})",
"What is played": "מה מתנגן",
"All back to the preset": "הכול חזרה לפריסט",
"Kept in your Pianoteq, bank «Ruach Studio», where Pianoteq itself finds it": "נשמר ב-Pianoteq שלך, בבנק \"Ruach Studio\", היכן ש-Pianoteq עצמו מוצא אותו",
"Keep in Pianoteq…": "שמירה ב-Pianoteq…",
"Pianoteq did not answer: {0}": "Pianoteq לא ענה: {0}",
"Now on {0}": "כעת על {0}",
"Pianoteq plays it…": "Pianoteq מנגן…",
"Played with this state": "נוגן עם המצב הזה",
"A name for this preset in your Pianoteq (bank «Ruach Studio»)": "שם לפריסט הזה ב-Pianoteq שלך (בנק \"Ruach Studio\")",
"Kept in Pianoteq: «{0}», bank «{1}»": "נשמר ב-Pianoteq: \"{0}\", בנק \"{1}\"",
"Find a preset, an instrument, a word": "חיפוש פריסט, כלי, מילה",
"{0} presets": "{0} פריסטים",
"No preset of these words": "אין פריסט עם המילים האלה",
"Pianoteq's own window: any of its presets, every setting it lets one set, heard before the stem is played": "החלון של Pianoteq עצמו: כל אחד מהפריסטים שלו, כל הגדרה שהוא מאפשר לשנות, נשמעים לפני שהסטם מנוגן",
"a demo in your Pianoteq: some of its keys are silent": "דמו ב-Pianoteq שלך: חלק מהקלידים שלו שותקים",
"The instruments your licence plays in full; the others are Pianoteq's demos, some of their keys silent": "הכלים שהרישיון שלך מנגן במלואם; האחרים הם דמו של Pianoteq, וחלק מהקלידים שלהם שותקים",
"Only what plays in full ({0} of {1})": "רק מה שמנגן במלואו ({0} מתוך {1})",
"demo": "דמו",
"Asking Pianoteq…": "שואל את Pianoteq…",
"No Pianoteq here": "אין כאן Pianoteq",
"no Pianoteq here: the guide's Pianoteq says where to put the one you bought": "אין כאן Pianoteq: הפרק \"Pianoteq\" במדריך אומר היכן לשים את זה שקנית",
"Be well!": "תהיה בריא!",
"{0} wants a wider screen: open it on a computer or a tablet. On a phone: the Musician, the Writer and the Librarian.": "{0} מבקש מסך רחב יותר: פתח אותו במחשב או בטאבלט. בטלפון: המוזיקאי, הכותב והספרן.",
"Into the silence": "אל השקט",
"Out of the silence": "מתוך השקט",
"Both alike": "שניהם באותה מידה",
"Fades of {0}–{1}": "פיידים של {0}–{1}",
"Into the silence {0} ms · out of it {1} ms": "אל השקט {0} ms · מתוכו {1} ms",
"A right-drag on a cut draws its fades; a right-click gives the sound back": "גרירה בכפתור הימני על חיתוך מציירת את הפיידים שלו; לחיצה ימנית מחזירה את הצליל",
"Unfold": "הרחבה",
"Fold its settings away: a click on its name opens them in its window": "קיפול ההגדרות שלו: לחיצה על השם שלו פותחת אותן בחלון שלו",
"Its settings back on its face": "ההגדרות שלו שוב עליו",
"Pianoteq": "Pianoteq",
"a stem played again on a piano": "סטם שנוגן מחדש על פסנתר",
"A stem of the set played again by the Pianoteq installed here (your own copy, bought and activated: the Studio ships none of it): its MIDI the take's own when the MIDI step made one of that stem, else transcribed here on the CPU; each note's touch read from the stem, the pedal held through each phrase, at the stem's level and length. A lane of its own in the DAW, or the stem's version. Its sound is not for training a model (Modartt's licence).": "סטם מהסט שמנוגן מחדש על ידי ה-Pianoteq המותקן כאן (העותק שלך, קנוי ועם אקטיבציה: הנפחות אינה כוללת דבר ממנו): ה-MIDI שלו הוא של הטייק עצמו כששלב ה-MIDI יצר אחד מהסטם הזה, אחרת הוא מתועתק כאן על ה-CPU; המגע של כל תו נקרא מהסטם, הפדל מוחזק לאורך כל פראזה, ברמה ובאורך של הסטם. רצועה משלו ב-DAW, או גרסה של הסטם. הצליל שלו אינו לאימון מודל (הרישיון של Modartt).",
"Stem": "סטם",
"Instrument": "כלי",
"In the DAW": "ב-DAW",
"Dynamics": "דינמיקה",
"Touch": "מגע",
"Sustain pedal": "פדל סוסטיין",
"What it plays": "מה הוא מנגן",
"Transpose, semitones": "טרנספוזיציה, חצאי טונים",
"Which stem the piano plays; a set without it gives the first of piano, other, instrumental, guitar": "איזה סטם הפסנתר מנגן; בסט שאין בו אותו נלקח הראשון מתוך piano, other, instrumental, guitar",
"A Pianoteq preset: an instrument you have not bought plays as a demo, some of its keys silent": "פריסט של Pianoteq: כלי שלא קנית מנגן כדמו, וחלק מהקלידים שלו שותקים",
"A lane of its own plays beside the stem; the stem's version plays in its place (the lane's version button)": "רצועה משלו מתנגנת לצד הסטם; הגרסה של הסטם מתנגנת במקומו (כפתור הגרסה של הרצועה)",
"Each note as loud as the stem played it at its attack, or all of them alike": "כל תו חזק כפי שהסטם ניגן אותו בהתקפה שלו, או כולם באותה מידה",
"Every velocity moved by this much: softer below zero, harder above": "כל ולוסיטי מוזז בשיעור הזה: רך יותר מתחת לאפס, קשה יותר מעליו",
"Down at a phrase's first note, up as its last one ends; a phrase ends where nothing sounds for 0.6 s": "למטה בתו הראשון של פראזה, למעלה כשהתו האחרון שלה מסתיים; פראזה מסתיימת היכן ששום דבר לא נשמע במשך 0.6 s",
"The stem's MIDI may hold several instruments: all of them, or only its pianos, keys and organs": "ה-MIDI של הסטם עשוי להכיל כמה כלים: את כולם, או רק את הפסנתרים, הקלידים והעוגבים שלו",
"Every note moved by this many semitones (12: an octave up), kept within the piano's 88 keys": "כל תו מוזז במספר הזה של חצאי טונים (12: אוקטבה למעלה), בתוך 88 הקלידים של הפסנתר",
