"C. Bechstein DG Felt I": "C. Bechstein DG Felt I",
"Classical Guitar": "Classical Guitar",
"Classical Guitar Warm": "Classical Guitar Warm",
"Classical Guitar Arpeggio": "Classical Guitar Arpeggio",
"How a node shows its settings": "איך צומת מציג את ההגדרות שלו",
"SIMPLE with Options Pop-Up": "SIMPLE עם חלון אפשרויות קופץ",
"A node is its name and what it does; a click opens its settings in a window.": "צומת הוא השם שלו ומה שהוא עושה; לחיצה פותחת את ההגדרות שלו בחלון.",
"FULL in ComfyUI Style": "FULL בסגנון ComfyUI",
"Every node carries all its settings on its face, as ComfyUI's do; a click on its name opens only what went in and what it made.": "כל צומת נושא את כל ההגדרות שלו על פניו, כמו ב-ComfyUI; לחיצה על שמו פותחת רק את מה שנכנס אליו ואת מה שהוא יצר.",
"Everything set here is heard as it is set and mixed on Forge as it is heard: the same EQ, compressor, pan, room and delay. A drag along a wave selects: drag the selection to move it (Ctrl copies), its edges to change it, right-click it to fade it in or out, raise, lower or silence it; Ctrl+C, Ctrl+X and Ctrl+V copy, cut and lay at the playhead, Delete silences, Ctrl+E splits, a double-click takes a segment whole. The line over a wave is its level: take it at a point up into a peak or down into a fade. A click plays from there; a right-click on a silence gives it back.": "כל מה שמוגדר כאן נשמע מיד, והמיקס על Forge נעשה בדיוק כפי שהוא נשמע: אותו EQ, קומפרסור, פאן, חדר ודיליי. גרירה לאורך גל בוחרת: גרור את הבחירה כדי להזיז אותה (Ctrl מעתיק), את קצותיה כדי לשנות אותה; לחיצה ימנית עליה נותנת פייד-אין או פייד-אאוט, הגברה, החלשה או השתקה; Ctrl+C, Ctrl+X ו-Ctrl+V מעתיקים, גוזרים ומניחים בסמן הניגון, Delete משתיק, Ctrl+E מפצל, לחיצה כפולה בוחרת מקטע שלם. הקו שמעל הגל הוא הרמה שלו: תפוס אותו בנקודה ומשוך למעלה לשיא או למטה לדעיכה. לחיצה מנגנת משם; לחיצה ימנית על שקט מחזירה את הצליל.",
"Selected {0}–{1}: drag it to move it (Ctrl copies), Ctrl+C copies, Ctrl+X cuts, Delete silences, a right-click for fades and level": "נבחר {0}–{1}: גרור כדי להזיז (Ctrl מעתיק), Ctrl+C מעתיק, Ctrl+X גוזר, Delete משתיק, לחיצה ימנית לפיידים ולרמה",
"A lane holds at most 64 splits": "ברצועה אחת לכל היותר 64 פיצולים",
"Split at {0}": "פוצל ב-{0}",
"Silenced {0}–{1}: a right-click on it gives it back": "הושתק {0}–{1}: לחיצה ימנית עליו מחזירה את הצליל",
"Cut {0}–{1}: silenced here, Ctrl+V lays it at the playhead": "נגזר {0}–{1}: כאן שקט, Ctrl+V מניח אותו בסמן הניגון",
"A lane holds at most 64 laid stretches: take one away first (a right-click on it)": "ברצועה אחת לכל היותר 64 מקטעים מונחים: הסר קודם אחד (לחיצה ימנית עליו)",
"Copied to {0}": "הועתק ל-{0}",
"Moved to {0}": "הוזז ל-{0}",
"Faded in over {0}–{1}": "פייד-אין על {0}–{1}",
"Faded out over {0}–{1}": "פייד-אאוט על {0}–{1}",
"Louder by 3 dB over {0}–{1}": "חזק יותר ב-3 dB על {0}–{1}",
"Quieter by 3 dB over {0}–{1}": "שקט יותר ב-3 dB על {0}–{1}",
"Cut out": "גזירה",
"Lay at the playhead": "הנחה בסמן הניגון",
"Silence it": "השתקה",
"Fade in from silence": "פייד-אין מהשקט",
"Fade out into silence": "פייד-אאוט אל השקט",
"Louder by 3 dB": "הגברה ב-3 dB",
"Quieter by 3 dB": "החלשה ב-3 dB",
"Split at its edges": "פיצול בקצוות",
"Select the whole lane": "בחירת הרצועה כולה",
"Joined at {0}": "חובר ב-{0}",
"Split at the playhead": "פיצול בסמן הניגון",
"Docked": "מעוגנת",
"The console beside the lanes, pinned, on hover or floating: every strip's inserts, sends, pan and fader, the returns and the master": "הקונסולה לצד הרצועות: מעוגנת, בריחוף או צפה; האינסרטים, הסנדים, הפאן והפיידר של כל ערוץ, הריטרנים והמאסטר",
"Where the console stands": "מיקום הקונסולה",
"On hover": "בריחוף",
"Floating": "צפה",
"On the right, a column of its own beside the lanes": "מימין, בעמודה משלה לצד הרצועות",
"A strip at the right edge: the pointer on it slides the console out over the lanes, away again when it leaves": "פס בקצה הימני: כשסמן העכבר עליו, הקונסולה גולשת החוצה מעל הרצועות, וחוזרת כשהוא עוזב",
"A panel of its own, moved by this row; it stays with the page and hides with its room": "חלונית נפרדת, שמזיזים אותה בשורה הזאת; היא נשארת עם הדף ומוסתרת יחד עם החדר שלה",
"Solo": "סולו",
"Unsolo": "ביטול סולו",
