"The Artist draws every shot that has no picture yet, two at a time on the free cards: the hero's shots from the hero's picture (Qwen-Image 2.1, then 2512 over it), the others by 2512 from their scene; each picture goes into its shot as it comes": "הצייר מצייר כל שוט שעדיין אין לו תמונה, שניים בכל פעם על הכרטיסים הפנויים: השוטים של הגיבור לפי התמונה של הגיבור (Qwen-Image 2.1, ואחריו 2512 מעליו), האחרים ב-2512 לפי הסצנה שלהם; כל תמונה נכנסת לשוט שלה ברגע שהיא מוכנה",
