"Pick the hero's picture first: «The look of the clip» → The hero": "בחר קודם את התמונה של הגיבור: \"המראה של הקליפ\" ← הגיבור",
"The Artist draws the {0} shots that have no picture yet?\n\n{1} of them with the hero: Qwen-Image 2.1 from the hero's picture, then 2512 over it; the others by 2512 from their scene. Two at a time on the free cards, about a minute a shot; each picture goes into its shot as it comes.": "לתת לצייר לצייר את {0} השוטים שעדיין אין להם תמונה?\n\n{1} מהם עם הגיבור: Qwen-Image 2.1 לפי התמונה של הגיבור, ואחריו 2512 מעליו; האחרים ב-2512 לפי הסצנה שלהם. שניים בכל פעם על הכרטיסים הפנויים, כדקה לשוט; כל תמונה נכנסת לשוט שלה ברגע שהיא מוכנה.",
"Every shot has its picture. Draw all {0} again? The pictures they have are put aside, not deleted.": "לכל שוט יש תמונה. לצייר את כל {0} מחדש? התמונות הקיימות יונחו בצד, לא יימחקו.",
