"Upscale all {0} shots that have a video with SeedVR2 7B sharp to 1080p?\n\nOn the free cards, about four minutes for a shot of four seconds; the clip takes each one as it comes. A shot's 🎬 menu has 1440p and the quick 3B.": "לעשות אפסקייל לכל {0} השוטים שיש להם וידאו עם SeedVR2 7B sharp ל-1080p?\n\nעל הכרטיסים הפנויים, כארבע דקות לשוט של ארבע שניות; הקליפ לוקח כל אחד ברגע שהוא מוכן. בתפריט 🎬 של שוט יש 1440p ואת 3B המהיר.",
