"7B sharp": "7B sharp",
"the quick one: 18.6 GB of a card at 1080p, 10 GB of RAM": "המהיר: 18.6 GB מהכרטיס ב-1080p, 10 GB של RAM",
"the Studio's own: 20 GB of a card at 1080p (16 of its blocks in RAM), 21 GB of RAM; 1440p fits too": "של הנפחות עצמה: 20 GB מהכרטיס ב-1080p (16 מהבלוקים שלו ב-RAM), 21 GB של RAM; גם 1440p נכנס",
"3B, 7B sharp and 7B": "3B, 7B sharp ו-7B",
"SeedVR2 (ByteDance, Apache-2.0) as numz packs it: the Videographer's upscaler, a shot's video to 1080p or 1440p in one step, the details made anew. Measured on an RTX 3090, 107 frames of 768p: 3B to 1080p in 284 s, 7B sharp in 367 s, 7B sharp to 1440p in 592 s": "SeedVR2 (ByteDance, Apache-2.0) באריזה של numz: האפסקיילר של הווידאוגרף, הווידאו של שוט ל-1080p או 1440p בצעד אחד, והפרטים נוצרים מחדש. נמדד על RTX 3090, 107 פריימים של 768p: 3B ל-1080p ב-284 s, 7B sharp ב-367 s, 7B sharp ל-1440p ב-592 s",
