"No style": "אין סגנון",
"No lyrics": "אין מילים",
"What the player in the rooms' footer and the window comparing takes stream: FLAC is the take itself, lossless (about 30 MB for a song of four minutes); Opus at 128 kbit/s is about 4 MB, made on the Studio's machine the first time a take plays, for a slow line (a phone, a VPN). Everywhere else the Studio hears and measures the lossless FLAC, and downloads stay WAV and FLAC.": "מה שהנגן בתחתית החדרים וחלון ההשוואה בין טייקים מזרימים: FLAC הוא הטייק עצמו, ללא אובדן (כ-30 MB לשיר של ארבע דקות); Opus ב-128 kbit/s הוא כ-4 MB, נוצר על המחשב של הנפחות בפעם הראשונה שטייק מתנגן, לחיבור איטי (טלפון, VPN). בכל מקום אחר הנפחות שומעת ומודדת את ה-FLAC ללא אובדן, וההורדות נשארות WAV ו-FLAC.",
"Videographer · MiniMax H3": "וידאוגרף · MiniMax H3",
"All int8 tiers": "כל רמות int8",
"the Studio's own: a card of 24 GB and 64 GB of RAM": "של הנפחות עצמה: כרטיס של 24 GB ו-64 GB של RAM",
"both modes whole and pruned, FastH3, ControlNet Union and the effects too": "שני המצבים, מלאים ומקוצצים, וגם FastH3, ControlNet Union והאפקטים",
"unquantized, for cards of 80 GB; on 24 GB only streamed from RAM, slowly": "ללא קוונטיזציה, לכרטיסים של 80 GB; על 24 GB רק בהזרמה מ-RAM, לאט",
"MiniMax H3 (MiniMax) as Comfy-Org packs it: the Videographer's moving pictures, a shot at a time on a card of 24 GB, the shot's picture its first frame. Its licence (the MiniMax H3 Community License) does not allow running it on your own machines in the United States, the European Union, the United Kingdom or South Korea, and commercial use beyond the threshold it names needs MiniMax's own licence. Where you run it and what you make with it is yours to answer for: read the licence before you fetch it": "MiniMax H3 (MiniMax) באריזה של Comfy-Org: התמונות הנעות של הווידאוגרף, שוט אחד בכל פעם על כרטיס של 24 GB, ותמונת השוט היא הפריים הראשון שלו. הרישיון שלו (MiniMax H3 Community License) אינו מתיר להריץ אותו על מחשבים משלך בארצות הברית, באיחוד האירופי, בבריטניה או בדרום קוריאה, ושימוש מסחרי מעבר לסף שהוא קובע מחייב רישיון נפרד מ-MiniMax. איפה אתה מריץ אותו ומה אתה יוצר איתו הם באחריותך: קרא את הרישיון לפני שאתה מוריד אותו",
"Shoot this shot with MiniMax H3: a draft (8 steps) or the final (28 steps); its picture, when it has one, is its first frame": "צילום השוט הזה עם MiniMax H3: טיוטה (8 צעדים) או סופי (28 צעדים); התמונה שלו, כשיש לו, היא הפריים הראשון",
"Every shot with MiniMax H3 as a draft (8 steps), shot by shot on the free cards; a shot's picture, when it has one, is its first frame": "כל השוטים עם MiniMax H3 כטיוטה (8 צעדים), שוט אחר שוט על הכרטיסים הפנויים; התמונה של שוט, כשיש לו, היא הפריים הראשון שלו",
"Shoot all {0} shots with MiniMax H3 as drafts?\n\nOn the free cards, a few minutes a shot; the clip takes each shot's video as it comes.": "לצלם את כל {0} השוטים עם MiniMax H3 כטיוטות?\n\nעל הכרטיסים הפנויים, כמה דקות לשוט; הקליפ לוקח את הווידאו של כל שוט ברגע שהוא מוכן.",
