"No MuScriptor model here: Engine → Models and LoRAs → Sound to MIDI fetches one": "אין כאן מודל MuScriptor: מנוע ← מודלים ו-LoRA ← צליל ל-MIDI מוריד אחד",
"Engine → Models and LoRAs": "מנוע ← מודלים ו-LoRA",
