"waits its turn": "ממתין לתורו",
"{0} % · {1} notes": "{0} % · תווים: {1}",
"Measure each card's VRAM": "מדידת ה-VRAM של כל כרטיס",
"Every card's VRAM peak at every step, in the step log; the run's card says each card's highest and the step it came at. For the runs after one that ran out of memory: which card fills first, and with what": "שיא ה-VRAM של כל כרטיס בכל צעד, ביומן הצעדים; כרטיס ההרצה מראה את השיא הגבוה ביותר של כל כרטיס ואת הצעד שבו הגיע. להרצות שאחרי הרצה שנגמר לה הזיכרון: איזה כרטיס מתמלא ראשון, ובמה",
"Shortest tracks to the first card": "הרצועות הקצרות ביותר לכרטיס הראשון",
"A step's shortest tracks go to the first card and the longest to the others: the first card holds more besides the run (about 2 GB of activations), so it is the one that runs out first": "הרצועות הקצרות ביותר של צעד הולכות לכרטיס הראשון והארוכות ביותר לאחרים: הכרטיס הראשון מחזיק יותר מלבד ההרצה (כ-2 GB של אקטיבציות), ולכן הזיכרון שלו נגמר ראשון",
"AR cap, tokens": "תקרת AR, טוקנים",
"A track whose music half reads more tokens than this trains Direct, without its score; still over, its song part is cut to fit. Their names go to ar-capped.txt beside the saves. 0: no cap": "רצועה שחצי המוזיקה שלה קורא יותר טוקנים מזה מתאמנת במצב Direct, בלי הפרטיטורה שלה; אם עדיין מעל, חלק השיר שלה נחתך כדי להיכנס. השמות שלהן נכתבים ל-ar-capped.txt לצד השמירות. 0: בלי תקרה",
"The meter and the guard: {0}.": "המודד והשומר: {0}.",
"each card's VRAM measured": "ה-VRAM של כל כרטיס נמדד",
"over {0} AR tokens a track trains Direct": "מעל {0} טוקני AR רצועה מתאמנת במצב Direct",
