"guard": "שומר",
"VRAM peaks": "שיאי VRAM",
"{0} GB at step {1}": "{0} GB בצעד {1}",
"Play from this shot": "ניגון מהשוט הזה",
"Copy this shot's prompt for a video model": "העתקת הפרומפט של השוט הזה למודל וידאו",
