"a double click plays from here": "לחיצה כפולה מנגנת מכאן",
"Downloads carry the take's stamp and its version: 20261028-185457_Song_·_Part_v1.0.1.flac": "ההורדות נושאות את חותמת הטייק ואת הגרסה שלו: 20261028-185457_Song_·_Part_v1.0.1.flac",
"Words of a take's title or its style; a take picked opens its plan here": "מילים משם הטייק או מהסגנון שלו; טייק שנבחר פותח כאן את התוכנית שלו",
"Open in the Videographer": "פתיחה בווידאוגרף",
