"Writer: the chat server at {0} does not answer. The Studio's own Writer is here:": "הכותב: שרת הצ'אט ב-{0} לא עונה. הכותב של הנפחות עצמה נמצא כאן:",
"Who is in the clip: each person as they look, the same in every shot": "מי בקליפ: כל אדם כפי שהוא נראה, זהה בכל שוט",
"Where the clip happens": "איפה הקליפ מתרחש",
"The clip's colours and light": "הצבעים והאור של הקליפ",
"How the clip moves through the song: its line from the first shot to the last": "איך הקליפ נע לאורך השיר: הקו שלו מהשוט הראשון עד האחרון",
"No note yet: a click writes one": "עדיין אין הערה: לחיצה כותבת אחת",
"Videographer": "וידאוגרף",
"The Videographer (beta): a take cut into shots at its sung lines, the look and every shot's scene written with the Writer; the moving pictures come with MiniMax H3": "הווידאוגרף (בטא): טייק חתוך לשוטים לפי השורות המושרות, המראה והסצנה של כל שוט נכתבים עם הכותב; התמונות הנעות מגיעות עם MiniMax H3",
"A take's song cut into shots at its sung lines, the look of the clip and each shot's scene, written with the Writer and yours to change. The moving pictures come with MiniMax H3.": "שיר של טייק חתוך לשוטים לפי השורות המושרות, המראה של הקליפ והסצנה של כל שוט, נכתבים עם הכותב ופתוחים לשינוי שלך. התמונות הנעות מגיעות עם MiniMax H3.",
"The moving pictures will come from MiniMax H3, which you download yourself from MiniMax's own repository: the Studio does not ship it. Its licence (the MiniMax Community License) does not allow running it on your own machines in the United States, the European Union, the United Kingdom or South Korea, and commercial use beyond the threshold it names needs MiniMax's own licence. Where you run it and what you make with it is yours to answer for: read the licence before you download it.": "התמונות הנעות יגיעו מ-MiniMax H3, שאתה מוריד בעצמך מהמאגר של MiniMax עצמה: הנפחות לא מספקת אותו. הרישיון שלו (MiniMax Community License) אינו מתיר להריץ אותו על מחשבים משלך בארצות הברית, באיחוד האירופי, בבריטניה או בדרום קוריאה, ושימוש מסחרי מעבר לסף שהוא קובע מחייב רישיון נפרד מ-MiniMax. איפה אתה מריץ אותו ומה אתה יוצר איתו הם באחריותך: קרא את הרישיון לפני שאתה מוריד אותו.",
