"A minute with the Studio counts when a page played or was in your hands in it; however many pages, a minute is one. The takes from their meta.json; the machine once a minute, kept by the hour; the folders without what their links lead to elsewhere.": "דקה עם הנפחות נספרת כשדף ניגן במהלכה או היה בידיים שלך; לא משנה כמה דפים, הדקה נספרת פעם אחת. הטייקים לפי ה-meta.json שלהם; המחשב פעם בדקה, נשמר לפי שעות; התיקיות בלי מה שהקישורים שלהן מובילים אליו במקום אחר.",
"One click: back to the start of this take (at its start already: the take above). Two clicks within a second: the take above in the list": "לחיצה אחת: חזרה לתחילת הטייק הזה (אם כבר בתחילתו: הטייק שמעליו). שתי לחיצות בתוך שנייה: הטייק שמעליו ברשימה",
