"The player's buttons and texts at rest": "הכפתורים והטקסטים של הנגן במנוחה",
"How solid the player's buttons, marks and times stand while the pointer is not on them; under the pointer they are always whole. The Studio's own: 60 %": "כמה אטומים הכפתורים, הסימונים והזמנים של הנגן כשסמן העכבר לא עליהם; מתחת לסמן הם תמיד מלאים. ברירת המחדל של הנפחות: 60 %",
