"Unprotect {0}? Its saves and the run itself can then be deleted.": "לבטל את ההגנה על {0}? אז אפשר יהיה למחוק את השמירות שלו ואת ההרצה עצמה.",
"Protected: neither its saves nor the run itself can be deleted; ⋯ → Unprotect to change that": "מוגן: אי אפשר למחוק לא את השמירות שלו ולא את ההרצה עצמה; ⋯ ← ביטול הגנה כדי לשנות זאת",
