"Delete {0} saves of {1} for good?": "למחוק לצמיתות שמירות של {1}: {0}?",
"{0} of them are in loras/, in the Musician's LoRAs. Take them out too (the space comes back), or keep them usable?": "מהן ב-loras/, ב-LoRA של המוזיקאי: {0}. להוציא גם אותן (המקום יתפנה), או להשאיר אותן זמינות לשימוש?",
"{0} saves deleted, {1} back on the disk": "שמירות שנמחקו: {0}, {1} התפנו בדיסק",
