"Play only": "לנגן רק",
"every take": "כל הטייקים",
"Only the takes with this mark play; the playlist keeps every take": "רק הטייקים עם הסימון הזה מתנגנים; הפלייליסט שומר את כל הטייקים",
"Up next": "הבא בתור",
"in {0} s": "בעוד {0} s",
"Play it now": "ניגון עכשיו",
"Which quant the Studio's writer runs: quality keeps the AutoRound 4 bits as they are (about 7.5 GB of VRAM), compact keeps those and lowers the rest (about 6.5 GB). Only those here can be chosen": "באיזו קוונטיזציה רץ כותב הנפחות: איכות שומרת את 4 הביטים של AutoRound כמו שהם (כ-7.5 GB של VRAM), קומפקטי שומר אותם ומוריד את השאר (כ-6.5 GB). אפשר לבחור רק את אלה שנמצאים כאן",
"Quality: the AutoRound 4 bits as they are (a 12 GB card)": "איכות: 4 הביטים של AutoRound כמו שהם (כרטיס של 12 GB)",
"Compact: for an 8 GB card": "קומפקטי: לכרטיס של 8 GB",
"Not here yet: Engine → Models and LoRAs → Studio writer fetches it (6.7 GB; compact 5.5 GB).": "עדיין לא כאן: מנוע ← מודלים ו-LoRA ← כותב הנפחות מוריד אותו (6.7 GB; הקומפקטי 5.5 GB).",
"Its weights are here; llama.cpp's llama-server is not built yet: launcher/extras.sh builds it.": "המשקלים שלו כאן; llama-server של llama.cpp עדיין לא נבנה: launcher/extras.sh בונה אותו.",
"Qwopus3.5-9B-v3 (Jackrong's, on Qwen3.5-9B, Apache-2.0), quantized with AutoRound, through llama.cpp on this machine: nothing leaves it. It starts at the first question and leaves the card after 10 minutes without one.": "Qwopus3.5-9B-v3 (של Jackrong, על בסיס Qwen3.5-9B, Apache-2.0), מקוונטז עם AutoRound, דרך llama.cpp על המחשב הזה: שום דבר לא יוצא ממנו. הוא עולה בשאלה הראשונה ומפנה את הכרטיס אחרי 10 דקות בלי שאלה.",
"not here": "לא כאן",
"llama-server not built": "llama-server לא נבנה",
"asleep": "ישן",
"on the processor": "על המעבד",
