"on GPU {0}": "על GPU {0}",
"Studio writer": "כותב הנפחות",
"Quality": "איכות",
"Compact": "קומפקטי",
"about 7.5 GB of VRAM with its 12K context: a 12 GB card": "כ-7.5 GB של VRAM עם הקונטקסט שלו של 12K: כרטיס של 12 GB",
"about 6.5 GB of VRAM with its 12K context: an 8 GB card": "כ-6.5 GB של VRAM עם הקונטקסט שלו של 12K: כרטיס של 8 GB",
"Qwopus3.5-9B-v3 (Jackrong's fine-tune of Qwen3.5-9B, Apache-2.0), quantized with AutoRound and moved into GGUF bit for bit, from goldhub/Ruach_Studio_Models_v2: the Writer's own language model on this machine, through llama.cpp (vendor/llama.cpp, built by launcher/extras.sh); Engine → Writer chooses between those here": "Qwopus3.5-9B-v3 (הפיינטיון של Jackrong ל-Qwen3.5-9B, Apache-2.0), מקוונטז עם AutoRound והועבר ל-GGUF ביט אחר ביט, מ-goldhub/Ruach_Studio_Models_v2: מודל השפה של הכותב עצמו על המחשב הזה, דרך llama.cpp (vendor/llama.cpp, נבנה על ידי launcher/extras.sh); מנוע ← הכותב בוחר בין אלה שכאן",
"← → keys": "מקשי ← →",
"Shift + ← →": "Shift + ← →",
"Start playing": "התחלת ניגון",
"when its first minute is in and the rest will come in time": "כשהדקה הראשונה הגיעה והשאר יגיע בזמן",
"when the whole take is in": "כשהטייק כולו הגיע",
"On a slow line (a studio far away), a take can start before all of it has come: once its first minute is in and the rest will come before the playing reaches it; where it changes to the whole, it does so at a quiet moment. At home the whole comes within seconds, and it waits for it either way.": "בחיבור איטי (נפחות רחוקה), טייק יכול להתחיל לפני שהגיע כולו: ברגע שהדקה הראשונה שלו הגיעה והשאר יגיע לפני שהניגון יגיע אליו; במקום שבו הוא מתחלף לקובץ השלם, זה קורה ברגע שקט. בבית הקובץ השלם מגיע תוך שניות, והוא ממתין לו בכל מקרה.",
"A click on a take plays it": "לחיצה על טייק מנגנת אותו",
"New takes play when they are done": "טייקים חדשים מתנגנים כשהם מוכנים",
"A double-click on a card plays or stops it": "לחיצה כפולה על כרטיס מנגנת או עוצרת אותו",
"Show disliked takes in the lists": "הצגת טייקים עם דיסלייק ברשימות",
"Each is the Studio's own until you change it here; the player's and the lists' own switches set the same.": "כל אחד הוא ברירת המחדל של הנפחות עד שתשנה אותו כאן; המתגים של הנגן ושל הרשימות עצמם קובעים אותו דבר.",
"The Studio's defaults": "ברירות המחדל של הנפחות",
