"Back to the last mark of every {#0} s; the ← key: every {#1} s, with Shift every {#2} s": "אחורה לסימון האחרון של כל {#0} s; מקש ←: כל {#1} s, עם Shift כל {#2} s",
"On to the next mark of every {#0} s; the → key: every {#1} s, with Shift every {#2} s": "קדימה לסימון הבא של כל {#0} s; מקש ←: כל {#1} s, עם Shift כל {#2} s",
"Copy the lines of the log shown": "העתקת השורות המוצגות ביומן",
"MIDI needs the Studio opened as localhost or over https; this page is {0}. From another computer: the Studio's https door, {1} (its own certificate: the browser asks once), or ssh -L {2} {3}, then {4}": "MIDI דורש שהנפחות תיפתח כ-localhost או דרך https; הדף הזה הוא {0}. ממחשב אחר: דלת ה-https של הנפחות, {1} (עם תעודה משלה: הדפדפן שואל פעם אחת), או ssh -L {2} {3}, ואז {4}",
