"The broken copy is kept in {0}.": "העותק השבור נשמר ב-{0}.",
"{0} is broken, and no snapshot holds it whole: it stays as it is.": "{0} שבור, ואף תמונת מצב לא מחזיקה אותו שלם: הוא נשאר כמו שהוא.",
"Topology": "טופולוגיה",
