"PCI address": "כתובת PCI",
"behind its own bridge {0}": "מאחורי גשר משלו {0}",
"X the card itself · PIX through one PCIe bridge · PXB through several bridges · PHB through a host bridge (the CPU) · NODE between host bridges of one NUMA node · SYS across the link between NUMA nodes (QPI/UPI) · NV# through # NVLinks": "X הכרטיס עצמו · PIX דרך גשר PCIe אחד · PXB דרך כמה גשרים · PHB דרך גשר מארח (ה-CPU) · NODE בין גשרים מארחים של צומת NUMA אחד · SYS דרך הקישור בין צמתי NUMA (QPI/UPI) · NV# דרך # NVLinks",
"P2P, a card reading another's memory directly: OK it can · CNS the chipset does not allow it · GNS the GPU does not · TNS the topology does not · NS not supported · U unknown": "P2P, כרטיס שקורא ישירות את הזיכרון של כרטיס אחר: OK אפשרי · CNS הצ'יפסט לא מאפשר · GNS ה-GPU לא מאפשר · TNS הטופולוגיה לא מאפשרת · NS לא נתמך · U לא ידוע",
"No NVIDIA card here: nvidia-smi is not on this machine.": "אין כאן כרטיס NVIDIA: nvidia-smi לא נמצא על המחשב הזה.",
"nvidia-smi does not answer: {0}": "nvidia-smi לא עונה: {0}",
