"Show the hidden again ({#0})": "הצגת המוסתרים שוב ({#0})",
"{#0} disliked stay out: the eye shows them": "מחוץ לרשימות בגלל דיסלייק: {#0}, העין מציגה אותם",
"Your markers could not be read ({0}): the project goes without them": "לא ניתן לקרוא את הסמנים שלך ({0}): הפרויקט יוצא בלעדיהם",
"A new build of the Studio is out: a reload takes it, and keeps the song in the form": "יצאה גרסה חדשה של הנפחות: טעינה מחדש תביא אותה ותשמור את השיר בטופס",
"The artwork is off {#0} of {#1} takes; not from the rest: {2}": "העטיפה הוסרה מ-{0} מתוך {1} טייקים; מהשאר לא: {2}",
"a file in user/ (user/c2pa/); empty: the Studio's own": "קובץ בתוך user/ (user/c2pa/); ריק: של הנפחות עצמה",
"the key file in user/ (user/c2pa/)": "קובץ המפתח בתוך user/ (user/c2pa/)",
"Cancelled: 1 more version of “{0}” was never sent": "בוטל: גרסה 1 נוספת של \"{0}\" לא נשלחה מעולם",
"Cancelled: 1 version of “{0}” sent while the question stood was cancelled too": "בוטל: גרסה 1 של \"{0}\" שנשלחה בזמן שהשאלה עמדה בוטלה גם היא",
"{#0} of them are not shown in the column: its search or filters leave them out.": "{0} מהם אינם מוצגים בעמודה: החיפוש או המסננים שלה משאירים אותם בחוץ.",
"The song library was read again, but the Librarian's catalog was not: {0}": "ספריית השירים נקראה שוב, אבל הקטלוג של הספרן לא: {0}",
