"The sung marks could not be read: {0}. The cards keep the ones read before": "לא ניתן היה לקרוא את סימני \"הושר עד הסוף\": {0}. הכרטיסים שומרים את אלה שנקראו קודם",
"locked": "נעול",
"Non-favourites to the trash…": "הלא-מועדפים לפח…",
"The takes of the column's workspace (every workspace under From all Workspaces) with no star, shield or lock go to the Librarian's trash; a take with a mark stays unless you tick it; asked first": "הטייקים של המרחב שבעמודה (כל המרחבים תחת \"מכל המרחבים\") שאין להם כוכב, מגן או מנעול הולכים לפח של הספרן; טייק עם סימון נשאר אלא אם תסמן אותו; קודם שואלים",
"Nothing went to the trash: the Librarian (Forge's lab) does not answer, and without it there is no trash to send takes to": "שום דבר לא הלך לפח: הספרן (המעבדה של Forge) לא עונה, ובלעדיו אין פח לשלוח אליו טייקים",
"No take in the column goes to the trash: each has a star, a shield or a lock, or is frozen, archived or hidden": "אף טייק בעמודה לא הולך לפח: לכל אחד יש כוכב, מגן או מנעול, או שהוא מוקפא, בארכיון או מוסתר",
"From all Workspaces, as the column shows them.": "מכל המרחבים, כפי שהעמודה מציגה אותם.",
"All Workspaces: the whole library.": "כל המרחבים: כל הספרייה.",
"The workspace in the column: “{0}”.": "המרחב שבעמודה: \"{0}\".",
"Without a star, a shield or a lock: {#0}. Those with no mark go to the trash, which gives them back until it is emptied.": "בלי כוכב, מגן או מנעול: {0}. אלה שאין להם סימון הולכים לפח, שמחזיר אותם עד שהוא מתרוקן.",
"Favourites stay: {#0}.": "מועדפים נשארים: {0}.",
"Protected takes stay: {#0}.": "טייקים מוגנים נשארים: {0}.",
"Takes in a workspace that locks them stay: {#0}.": "טייקים במרחב שנועל אותם נשארים: {0}.",
