"Takes kept only in this tab stay: {#0}.": "טייקים שנשמרים רק בכרטיסייה הזאת נשארים: {0}.",
"A take with a mark stays unless each of its marks is ticked below.": "טייק עם סימון נשאר אלא אם כל הסימונים שלו מסומנים למטה.",
