"Untick all": "ביטול הסימון של הכול",
"with a reaction": "עם תגובה",
"in a published 💎 set": "בסט 💎 שפורסם",
"To the trash {#0}": "לפח {0}",
"Nothing went to the trash: every take left has a mark you did not tick": "שום דבר לא הלך לפח: לכל טייק שנשאר יש סימון שלא סימנת",
