"A diffusion upscaler, the Videographer's own: it makes the details anew rather than sharpening them, any factor in one step; 7B sharp in the precision the card's free memory takes, 3B where no 7B fits": "אפסקיילר דיפוזיה, זה של הווידאוגרף: הוא יוצר את הפרטים מחדש במקום לחדד אותם, כל מקדם בצעד אחד; 7B sharp בדיוק שהזיכרון הפנוי של הכרטיס מאפשר, 3B היכן ש-7B לא נכנס",
"Compare: first and second": "השוואה: ראשון ושני",
"two to four, each against the first checked": "שניים עד ארבעה, כל אחד מול הראשון שסומן",
"Pick for First and second": "בחירה ל\"ראשון ושני\"",
"Pick it for First and second, up to four: numbered 1 to 4 as picked, 1 the one the others are measured against; a fifth takes the place of the oldest": "בחר אותו ל\"ראשון ושני\", עד ארבעה: ממוספרים 1 עד 4 לפי סדר הבחירה, ומול 1 נמדדים האחרים; חמישי תופס את מקומו של הוותיק ביותר",
"First and second of the versions picked on their rows, two to four, measured against 1: the measures side by side, the spectrograms of each, the difference of a chosen pair, a verdict": "\"ראשון ושני\" לגרסאות שנבחרו בשורות שלהן, שתיים עד ארבע, נמדדות מול 1: המדידות זו לצד זו, הספקטרוגרמות של כל אחת, ההבדל של זוג נבחר, פסק דין",
"Pick two to four versions on their rows first": "בחר קודם שתיים עד ארבע גרסאות בשורות שלהן",
"Measuring them against the first…": "מודד אותן מול הראשונה…",
