"{1} − {0}: red where it is louder, blue where it is quieter (±6 dB)": "{1} − {0}: אדום היכן שהוא חזק יותר, כחול היכן שהוא שקט יותר (±6 dB)",
"time, s": "זמן, s",
"Average spectrum at equal loudness": "ספקטרום ממוצע בעוצמה שווה",
"What changed in the tone (grey: ±1 dB) · blue: what no filter makes": "מה השתנה בטון (אפור: ±1 dB) · כחול: מה ששום פילטר לא יוצר",
