"{1} − {0}, dB": "{1} − {0}, dB",
"Dynamics: glue {0} dB, peaks {1} dB": "דינמיקה: הדבקה {0} dB, שיאים {1} dB",
"Short-term loudness": "עוצמה לטווח קצר",
"The two are not one music (likeness {0}): what follows compares two different sounds.": "השניים אינם אותה מוזיקה (דמיון {0}): מה שבא להלן משווה שני צלילים שונים.",
"{1} comes {0} ms later than {2}; compared from where they meet.": "{1} מגיע {0} ms אחרי {2}; ההשוואה מתחילה מהמקום שבו הם נפגשים.",
"The polarity of {0} is inverted against {1}.": "הקוטביות של {0} הפוכה ביחס ל-{1}.",
"{0} is {1} LU quieter than {2}; everything below compares them at equal loudness.": "{0} שקט ב-{1} LU מ-{2}; כל מה שלמטה משווה ביניהם בעוצמה שווה.",
"{0} is {1} LU louder than {2}; everything below compares them at equal loudness.": "{0} חזק ב-{1} LU מ-{2}; כל מה שלמטה משווה ביניהם בעוצמה שווה.",
"The tone stayed: no sixth-octave band moved by half a dB.": "הטון נשאר: אף רצועה של שישית אוקטבה לא זזה בחצי dB.",
"The tone of {0} against {1}: {2}.": "הטון של {0} מול {1}: {2}.",
"The most at {0} Hz: {1} dB.": "הכי הרבה ב-{0} Hz: {1} dB.",
"The loud moments lost {0} dB against the middle ones: compression, a glue.": "הרגעים החזקים איבדו {0} dB ביחס לבינוניים: דחיסה, הדבקה.",
"The loud moments gained {0} dB against the middle ones: the dynamics opened.": "הרגעים החזקים הרוויחו {0} dB ביחס לבינוניים: הדינמיקה נפתחה.",
"The dynamics stayed: the loud and the middle moments moved alike.": "הדינמיקה נשארה: הרגעים החזקים והבינוניים זזו באותה מידה.",
"The sharpest 10 ms peaks came down {0} dB at equal loudness: they are shaved.": "השיאים החדים ביותר של 10 ms ירדו ב-{0} dB בעוצמה שווה: הם גולחו.",
"The sharpest 10 ms peaks stand {0} dB higher at equal loudness: they are not shaved; a turned phase can raise them.": "השיאים החדים ביותר של 10 ms עומדים {0} dB גבוה יותר בעוצמה שווה: הם לא גולחו; פאזה מסובבת יכולה להרים אותם.",
"The sharpest peaks stayed where they were against the loudness.": "השיאים החדים ביותר נשארו במקומם ביחס לעוצמה.",
"Peak over loudness {0} → {1} dB.": "שיא מעל העוצמה {0} ← {1} dB.",
