"The stereo: correlation {0} → {1}, width {2} → {3} dB.": "הסטריאו: מתאם {0} ← {1}, רוחב {2} ← {3} dB.",
"Left against right {0} → {1} dB: one side lost or gained.": "שמאל מול ימין {0} ← {1} dB: צד אחד איבד או הרוויח.",
"{0} clipped runs in {1} ({2} had {3}).": "{0} רצפי קליפינג ב-{1} (ב-{2} היו {3}).",
"What no filter makes of {1} from {2}: {0} dB under the music (distortion, noise, pumping); an EQ or a delay alone leaves it near −40.": "מה ששום פילטר לא יוצר מ-{2} ב-{1}: {0} dB מתחת למוזיקה (עיוות, רעש, פאמפינג); אקולייזר או דיליי לבדם משאירים אותו קרוב ל-−40.",
"Most of it at {0} Hz ({1} dB).": "רובו ב-{0} Hz ({1} dB).",
"Most of it at {0} Hz ({1} dB) and {2} Hz ({3} dB).": "רובו ב-{0} Hz ({1} dB) וב-{2} Hz ({3} dB).",
"Key: {0} (in any keyboard layout)": "מקש: {0} (בכל פריסת מקלדת)",
"Loop start": "תחילת הלופ",
"Loop end": "סוף הלופ",
"The loop's start: drag it, or ← → while it has the focus (0.1 s, with Shift 1 s)": "תחילת הלופ: גרור אותה, או ← → כשהיא בפוקוס (0.1 s, עם Shift 1 s)",
"The loop's end: drag it, or ← → while it has the focus (0.1 s, with Shift 1 s)": "סוף הלופ: גרור אותו, או ← → כשהוא בפוקוס (0.1 s, עם Shift 1 s)",
"Mark this moment (M): a word at this moment goes into the take's note to the millisecond, and a flag stands on the wave. Shift+drag on the wave flags a stretch; a double click on a flag or a stretch changes its word": "סימון הרגע הזה (M): מילה ברגע הזה נכנסת להערה של הטייק עד המילישנייה, ודגל עומד על צורת הגל. Shift+גרירה על צורת הגל מסמנת קטע; לחיצה כפולה על דגל או על קטע משנה את המילה שלו",
"Flag this stretch {0}": "סימון הקטע הזה {0}",
"A word or two: it goes into the take's note as a line with the stretch's start and end, and a shaded band stands on the wave; a click on the band's top plays it.": "מילה או שתיים: היא נכנסת להערה של הטייק כשורה עם ההתחלה והסוף של הקטע, ופס מוצלל עומד על צורת הגל; לחיצה על החלק העליון של הפס מנגנת אותו.",
