"The Artist draws the {0} shots that have no picture yet?\n\n{1} of them with the hero: Qwen-Image 2.1 from the hero's picture, then 2512 over it; the others by 2512 from their scene. On every free card at once, each card loading its painter once for all its shots; each picture goes into its shot as it comes.": "שהצייר יצייר את {0} השוטים שעדיין אין להם תמונה?\n\n{1} מהם עם הגיבור: Qwen-Image 2.1 מהתמונה של הגיבור, ואז 2512 מעליה; האחרים ב-2512 מהסצנה שלהם. על כל כרטיס פנוי בבת אחת, וכל כרטיס טוען את הצייר שלו פעם אחת לכל השוטים שלו; כל תמונה נכנסת לשוט שלה כשהיא מוכנה.",
"Upscale all {0} shots that have a video with {1} to 1080p?\n\nOn every free card at once, each card loading it once for its share; the clip takes each one as it comes.": "לבצע אפסקייל ל-1080p לכל {0} השוטים שיש להם וידאו, עם {1}?\n\nעל כל כרטיס פנוי בבת אחת, וכל כרטיס טוען אותו פעם אחת לחלק שלו; הקליפ לוקח כל אחד כשהוא מוכן.",
"Upscale all {0} shots that have a video with {1} to 720p? The clip scales them to its size.\n\nOn every free card at once, each card loading it once for its share; the clip takes each one as it comes.": "לבצע אפסקייל ל-720p לכל {0} השוטים שיש להם וידאו, עם {1}? הקליפ יביא אותם לגודל שלו.\n\nעל כל כרטיס פנוי בבת אחת, וכל כרטיס טוען אותו פעם אחת לחלק שלו; הקליפ לוקח כל אחד כשהוא מוכן.",
"This would wait, and how long is not known": "זה ימתין, ולא ידוע כמה זמן",
"This would wait at least {0} min": "זה ימתין לפחות {0} דק'",
"This would wait about {0} min": "זה ימתין בערך {0} דק'",
"Wait (how long is not known; music and speech wait behind it)": "המתנה (לא ידוע כמה זמן; מוזיקה ודיבור ממתינים מאחוריו)",
"Wait (at least {0} min; music and speech wait behind it)": "המתנה (לפחות {0} דק'; מוזיקה ודיבור ממתינים מאחוריו)",
"Wait (about {0} min; music and speech wait behind it)": "המתנה (בערך {0} דק'; מוזיקה ודיבור ממתינים מאחוריו)",
"The cards the song needs are busy with long work:": "הכרטיסים שהשיר צריך עסוקים בעבודה ארוכה:",
"The cards the reading needs are busy with long work:": "הכרטיסים שהקריאה צריכה עסוקים בעבודה ארוכה:",
"· {0} on GPU {1}: about {2} min left": "· {0} על GPU {1}: נשארו בערך {2} דק'",
"· {0} on GPU {1}: how long it has left is not known": "· {0} על GPU {1}: לא ידוע כמה זמן נשאר לו",
"· {0}: about {1} min left": "· {0}: נשארו בערך {1} דק'",
"· {0}: how long it has left is not known": "· {0}: לא ידוע כמה זמן נשאר לו",
"Music and speech asked after it wait behind it.": "מוזיקה ודיבור שהתבקשו אחריו ממתינים מאחוריו.",
"“{0}” waits for the cards": "\"{0}\" ממתין לכרטיסים",
"You chose to wait for it (about {0} min); music and speech asked after it wait behind it, so “{1}” is not queued now.": "בחרת להמתין לו (בערך {0} דק'); מוזיקה ודיבור שהתבקשו אחריו ממתינים מאחוריו, ולכן \"{1}\" לא נכנס לתור עכשיו.",
"You chose to wait for it; music and speech asked after it wait behind it, so “{0}” is not queued now.": "בחרת להמתין לו; מוזיקה ודיבור שהתבקשו אחריו ממתינים מאחוריו, ולכן \"{0}\" לא נכנס לתור עכשיו.",
"Take “{0}” off the queue": "הוצאת \"{0}\" מהתור",
"Keep it waiting": "השארה בהמתנה",
"Not queued: “{0}” waits for the cards first": "לא בתור: \"{0}\" ממתין קודם לכרטיסים",
"Taken off the queue: “{0}”": "הוצא מהתור: \"{0}\"",
"The cards are free: “{0}” goes now": "הכרטיסים פנויים: \"{0}\" יוצא עכשיו",
"Queued to wait: “{0}” (about {1} min)": "בתור להמתנה: \"{0}\" (בערך {1} דק')",
"Queued to wait: “{0}”": "בתור להמתנה: \"{0}\"",
"Waiting for the cards: “{0}” goes when they are free (about {1} min)": "ממתין לכרטיסים: \"{0}\" ייצא כשהם יתפנו (בערך {1} דק')",
"Waiting for the cards: “{0}” goes when they are free": "ממתין לכרטיסים: \"{0}\" ייצא כשהם יתפנו",
"Ask before music or speech waits longer than": "לשאול לפני שמוזיקה או דיבור ממתינים יותר מאשר",
"When a song or a reading would wait behind long work (the Videographer, the Artist, a training, an upscale) longer than this, the Studio asks first: wait, and the music and speech asked after it wait behind it, or take it off the queue. The wait is reckoned from the running jobs' own progress; when it cannot be, the question says so": "כששיר או קריאה היו ממתינים מאחורי עבודה ארוכה (הווידאוגרף, הצייר, אימון, אפסקייל) יותר מזה, הנפחות שואלת קודם: להמתין, ואז המוזיקה והדיבור שהתבקשו אחריהם ממתינים מאחוריהם, או להוציא מהתור. ההמתנה מחושבת לפי ההתקדמות של המשימות הרצות עצמן; כשאי אפשר לחשב אותה, השאלה אומרת זאת",
