// HERESY 2377, 2378 (code-a): the transcriber's modes and the decoders' tips
RuachI18n.add("he", {
"m-a-p's decoder": "המפענח של m-a-p",
"ours, the default": "שלנו, ברירת המחדל",
"ours, its second branch": "שלנו, הענף השני שלו",
"Standard: m-a-p's decoder, the one released with YuE2. Covers and uploads are encoded with it too.": "Standard: המפענח של m-a-p, זה שיצא יחד עם YuE2. גם קאברים והעלאות מקודדים בו.",
"RS x3 v1: our decoder (YuE2-VAE-RS x3), m-a-p's Standard grown to three times its size and trained on music; the Studio's default. Float32 only: slower than Standard and hungrier; on a small card it makes room for itself and leaves after the song.": "RS x3 v1: המפענח שלנו (YuE2-VAE-RS x3), ה-Standard של m-a-p שהוגדל פי שלושה ואומן על מוזיקה; ברירת המחדל של הסטודיו. float32 בלבד: איטי יותר מ-Standard וזולל יותר; בכרטיס קטן הוא מפנה לעצמו מקום ויוצא אחרי השיר.",
"RS x3 v2: the second branch of our decoder, trained the same way with a gentler weight on the highs. Float32 only, like v1: slower than Standard.": "RS x3 v2: הענף השני של המפענח שלנו, מאומן באותה דרך עם משקל עדין יותר על הגבוהים. float32 בלבד, כמו v1: איטי יותר מ-Standard.",
"stock: m-a-p's decoder, released with YuE2": "מקורי: המפענח של m-a-p, יצא עם YuE2",
"ours: Standard grown three times and trained on music; the default": "שלנו: Standard שהוגדל פי שלושה ואומן על מוזיקה; ברירת המחדל",
"ours: its second branch, a gentler weight on the highs": "שלנו: הענף השני שלו, משקל עדין יותר על הגבוהים",
"The sound decoder for the songs to come. A take already made decodes again with another one from its card, in seconds.\nRS x3 v1 · ours: Standard grown three times and trained on music, the default\nRS x3 v2 · its second branch, trained with a gentler weight on the highs\nStandard · m-a-p's decoder, released with YuE2\nOurs run in float32 only, slower than Standard": "מפענח הצליל לשירים הבאים. טייק שכבר נעשה מתפענח מחדש עם מפענח אחר מהכרטיס שלו, בתוך שניות.\nRS x3 v1 · שלנו: Standard שהוגדל פי שלושה ואומן על מוזיקה, ברירת המחדל\nRS x3 v2 · הענף השני שלו, מאומן עם משקל עדין יותר על הגבוהים\nStandard · המפענח של m-a-p, יצא עם YuE2\nשלנו רצים ב-float32 בלבד, איטיים יותר מ-Standard",
"m-a-p's decoder, released with YuE2": "המפענח של m-a-p, יצא עם YuE2",
"m-a-p's decoder, the one released with YuE2. Covers and uploads are encoded with it too.": "המפענח של m-a-p, זה שיצא יחד עם YuE2. גם קאברים והעלאות מקודדים בו.",
"SheetSage2 by m-a-p with its rotary angles rounded to bfloat16, as it was trained: the base and the default. MERT, the ear SheetSage2 listens with, places every moment of the song by these angles; computed exactly, they are not the ones it learnt, and its bars and meters drift (on twenty of our songs: 82 false meter changes with exact angles, 8 with these, where the songs have 9). Its risk: a rare false meter change can still slip in.": "SheetSage2 של m-a-p עם זוויות הסיבוב מעוגלות ל-bfloat16, כפי שאומן: הבסיס וברירת המחדל. MERT, האוזן שבה SheetSage2 מקשיב, ממקם כל רגע בשיר לפי הזוויות האלה; כשהן מחושבות במדויק, הן אינן אלה שעליהן למד, והתיבות והמשקלים זזים (בעשרים משירינו: 82 החלפות משקל שגויות עם זוויות מדויקות, 8 עם אלה, כשבשירים יש 9). הסיכון שלו: החלפת משקל שגויה נדירה עדיין עלולה לחמוק.",
"Not our fine-tune: SheetSage2-Refined is anime-song's community fine-tune of m-a-p's SheetSage2 (CC BY-NC 4.0), run with bfloat16 angles as its author's reference runs it. On twenty of our songs it wrote every score: the bar count right on 9 (Heretical 8), odd meters and a drill's half time heard, slash and tension chords. Its risk: a wider chord vocabulary than the song model learnt from SheetSage2, so its rarer chords are new words to it; in a song where it hears no chords, it writes none.": "לא הכוונון שלנו: SheetSage2-Refined הוא כוונון קהילתי של anime-song על SheetSage2 של m-a-p (CC BY-NC 4.0), עם זוויות bfloat16 כפי שההפניה של יוצרו מריצה אותו. בעשרים משירינו כתב כל פרטיטורה: מספר התיבות מדויק ב-9 (Heretical 8), שומע משקלים אי-זוגיים וחצי הטמפו של דריל, כותב אקורדים עם בס ועם מתחים. הסיכון שלו: אוצר אקורדים רחב יותר ממה שמודל השיר למד מ-SheetSage2, והאקורדים הנדירים שלו הם מילים חדשות עבורו; בשיר שבו אינו שומע אקורדים, אינו כותב אף אחד.",
"Who writes the sheets of Full and Melody: Heretical (SheetSage2 with the bf16 angles it was trained with; a new set's default) or Refined (SheetSage2-Refined, anime-song's community fine-tune, not ours: odd meters, slash and tension chords, wider than what the song model knows; a run of its own, never mixed). A set keeps the transcriber its sheets were written by: a set made before 2.0.7 shows Standard (SheetSage2 with exact angles) and keeps it. Each keeps its own sheets beside the set.": "מי כותב את הפרטיטורות של Full ו-Melody: Heretical (SheetSage2 עם זוויות bf16 שעליהן אומן; ברירת המחדל לסט חדש) או Refined (SheetSage2-Refined, כוונון קהילתי של anime-song, לא שלנו: משקלים אי-זוגיים, אקורדים עם בס ועם מתחים, רחבים ממה שהמודל מכיר; אימון נפרד, לעולם לא מעורבב). סט שומר את המתעתק שבו נכתבו הפרטיטורות שלו: סט מלפני 2.0.7 מציג Standard (SheetSage2 עם זוויות מדויקות) ושומר עליו. כל אחד שומר את הפרטיטורות שלו לצד הסט.",
"anime-song's community fine-tune of m-a-p's SheetSage2, the Refined transcriber: not ours (CC BY-NC 4.0)": "כוונון קהילתי של anime-song על SheetSage2 של m-a-p, המתעתק Refined: לא שלנו (CC BY-NC 4.0)",
"Refined's frame heads, grammar and rescoring, ported into our engine (MIT)": "ראשי המסגרות, הדקדוק והניקוד מחדש של Refined, שהועברו למנוע שלנו (MIT)",
});
// end of HERESY 2377, 2378

